window.TADABBUR_HUD = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة هود (١١)، سورةٌ مكّيّةٌ في التوحيدِ وقصصِ الأنبياء (نوح، هود، صالح، إبراهيم، لوط، شعيب، موسى) والثباتِ على الحق. تُفتتَح بـ«الر». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":11,"name":"هود","total_ayahs":123,"audio":[6,41,56,61,88,90,112,113,114,123],"passages":[{"title":"كتابٌ أُحكمت آياتُه، ودعوةُ التوحيدِ والاستغفار","range":[1,4],"theme":"إحكامُ القرآنِ وتفصيلُه، وأصلُ الدعوةِ: عبادةُ الله والاستغفارُ والتوبة","verses":[{"n":1,"reflection":{"text":"«الر كتاب أحكمت آياته ثم فصلت من لدن حكيم خبير»: افتُتحت السورةُ بـ«الر» تنبيهًا على إعجازِ القرآنِ من جنسِ حروفِهم؛ ثم أخبر أنّ هذا كتابٌ أُحكمت آياتُه فلا خللَ فيها ولا تناقض، ثم فُصّلت وبُيّنت أحكامًا وقصصًا ومواعظَ من عند حكيمٍ في أفعاله خبيرٍ ببواطنِ الأمور؛ فالقرآنُ محكمٌ مفصّلٌ من لدن حكيمٍ خبير؛ فعظّمه وتدبّر إحكامَه وتفصيله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكيم","الخبير"],"heart_state":{"text":"تعظيمُ القرآنِ لإحكامِ آياته وحكمةِ منزّله."},"action":{"text":"عظّم القرآنَ وتدبّر آياته المحكمةَ المفصّلة، واعلم أنه من لدن حكيمٍ خبير، فاعمل بما فصّل من أحكامه."}},{"n":2,"reflection":{"text":"«ألا تعبدوا إلا الله إنني لكم منه نذير وبشير»: مضمونُ هذا الكتابِ ودعوتُه: ألّا تعبدوا إلا الله وحده لا شريك له؛ يقول النبيُّ ﷺ: إنني لكم من الله نذيرٌ من عذابه لمن كفر، وبشيرٌ بثوابه لمن آمن وأطاع؛ ففي هذا أنّ لبَّ الرسالةِ التوحيد، وأنّ الرسولَ بين إنذارٍ وبشارة؛ فأخلص عبادتك لله وحده، وكن بين خوفِ نذارتِه ورجاءِ بشارته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله، والعيشُ بين الخوفِ والرجاء."},"action":{"text":"اعبد الله وحده مخلصًا، وعش بين إنذارِ الله ورجاءِ بشارته، فذاك لبُّ رسالةِ الأنبياء."}},{"n":3,"reflection":{"text":"«وأن استغفروا ربكم ثم توبوا إليه يمتعكم متاعا حسنا إلى أجل مسمى ويؤت كل ذي فضل فضله وإن تولوا فإني أخاف عليكم عذاب يوم كبير»، واطلبوا مغفرةَ ربّكم لما سلف من ذنوبكم، ثم توبوا إليه بالإقبالِ على طاعته، فإن فعلتم متّعكم في الدنيا متاعًا حسنًا (سَعةً وطيبَ عيشٍ) إلى انتهاءِ آجالكم، وأعطى كلَّ صاحبِ عملٍ فاضلٍ جزاءَ فضله في الآخرة؛ وإن أعرضتم فإني أخاف عليكم عذابَ يومٍ عظيمٍ (القيامة)؛ ففي الاستغفارِ والتوبةِ سعةُ العيشِ وحسنُ الجزاء؛ فأكثر من الاستغفارِ والتوبةِ تُرزق طيبَ الحياةِ وجزيلَ الأجر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ملازمةُ الاستغفارِ والتوبةِ رجاءَ سَعةِ العيشِ وحسنِ الجزاء."},"action":{"text":"أكثر من الاستغفارِ والتوبةِ إلى الله، فبهما يُمتّعك متاعًا حسنًا في الدنيا ويؤتيك فضله في الآخرة."}},{"n":4,"reflection":{"text":"«إلى الله مرجعكم وهو على كل شيء قدير»: إلى الله وحده مصيركم يوم القيامةِ للحسابِ والجزاء، وهو على كلِّ شيءٍ قديرٌ لا يعجزه بعثُكم بعد الموتِ ولا مجازاتُكم؛ ففي هذا حثٌّ على الاستعدادِ للرجوعِ إلى القديرِ الذي لا يعجزه شيء؛ فاستعدّ للقاءِ ربّك، واعلم أنه قادرٌ على بعثك وجزائك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"الاستعدادُ للرجوعِ إلى الله القديرِ على كلِّ شيء."},"action":{"text":"استعدّ للقاءِ الله، واعلم أنّ مرجعك إليه وهو القادرُ على بعثك ومجازاتك، فاعمل لهذا اللقاء."}}]},{"title":"إحاطةُ علمِ الله بالسرائر، وكفالتُه لأرزاقِ الخلق","range":[5,7],"theme":"أنّ الله يعلم ما تُخفي الصدور، ويرزق كلَّ دابّة، وخلق الكونَ لابتلاءِ العمل","verses":[{"n":5,"reflection":{"text":"«ألا إنهم يثنون صدورهم ليستخفوا منه ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون إنه عليم بذات الصدور»: ألا إنّ المشركين يطوون صدورهم ويخفون ما فيها من عداوةٍ ليستتروا من الله (أو من رسوله)؛ ألا حين يتغطّون بثيابهم مستترين، يعلم الله ما يخفون في قلوبهم وما يظهرون بألسنتهم؛ إنه عليمٌ بما تنطوي عليه الصدور من خيرٍ وشرّ؛ ففي هذا أنه لا يخفى على الله شيء؛ فاستحضر علمَ الله بسرّك، وطهّر قلبك ممّا يكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عليم بذات الصدور"],"heart_state":{"text":"استحضارُ علمِ الله بخفايا الصدورِ فيستقيمُ الباطن."},"action":{"text":"طهّر قلبك من كلِّ ما يكره الله، واستحضر أنه عليمٌ بذاتِ الصدور، لا يخفى عليه سرُّك مهما استترت."}},{"n":6,"reflection":{"text":"«وما من دابة في الأرض إلا على الله رزقها ويعلم مستقرها ومستودعها كل في كتاب مبين»، وما من مخلوقٍ يدبُّ في الأرضِ إلا وقد تكفّل الله برزقه فضلًا منه، ويعلم مستقرَّها (مأواها) ومستودعها (حيث تموت أو حيث كانت في الأصلاب)، كلُّ ذلك مثبتٌ في كتابٍ مبينٍ (اللوحِ المحفوظ)؛ ففي هذا كمالُ علمِ الله وسَعةُ رزقه؛ فاطمئن إلى أنّ رازقك هو الذي رزق كلَّ دابّة، ولا تحمل همَّ الرزق.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرزاق"],"heart_state":{"text":"الاطمئنانُ إلى كفالةِ الله بالرزق، وطرحُ همِّه."},"action":{"text":"اطمئن إلى أنّ رزقك على الله الذي تكفّل برزقِ كلِّ دابّة، واطلبه بالسببِ المشروع، ولا تحمل همَّ الرزقِ الزائد."}},{"n":7,"reflection":{"text":"«وهو الذي خلق السماوات والأرض في ستة أيام وكان عرشه على الماء ليبلوكم أيكم أحسن عملا ولئن قلت إنكم مبعوثون من بعد الموت ليقولن الذين كفروا إن هذا إلا سحر مبين»، وهو الذي خلق السماواتِ والأرضَ في ستةِ أيامٍ بحكمته، وكان عرشُه على الماءِ قبل خلقهما، وخلق ذلك ليختبركم أيّكم أحسنُ عملًا (أخلصُه وأصوبُه)؛ ولئن قلت لهم إنكم مبعوثون بعد الموتِ ليقولنّ الكافرون: ما هذا القرآنُ إلا سحرٌ ظاهر! ففي هذا أنّ الغايةَ من الخلقِ ابتلاءُ العملِ لا كثرتُه بل حُسنُه؛ فأحسن عملك بالإخلاصِ والمتابعة، فالغايةُ أحسنُ العملِ لا أكثرُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ إحسانِ العملِ (إخلاصًا وصوابًا) لأنه غايةُ الابتلاء."},"action":{"text":"احرص على إحسانِ عملك لا مجرّدِ كثرته: أخلصه لله واجعله على سنّةِ نبيّه، فذاك مقصودُ خلقك وابتلائك."}}]},{"title":"استعجالُ العذاب، وتقلّبُ الإنسانِ بين اليأسِ والفخر","range":[8,11],"theme":"طبيعةُ الإنسانِ الجزوعةُ الفخورة، واستثناءُ الصابرين العاملين","verses":[{"n":8,"reflection":{"text":"«ولئن أخرنا عنهم العذاب إلى أمة معدودة ليقولن ما يحبسه ألا يوم يأتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزئون»، ولئن أخّرنا عن هؤلاء المكذّبين العذابَ إلى وقتٍ محدودٍ معدود، ليقولنّ استهزاءً واستبعادًا: ما الذي يمنع نزولَه إن كان حقًّا؟ ألا إنه يوم يأتيهم لا يُصرف عنهم ولا يُدفع، وأحاط بهم العذابُ الذي كانوا يستهزئون به؛ ففي هذا أنّ تأخّرَ العقوبةِ ليس دليلَ نجاة؛ فلا تستبطئ وعيدَ الله ولا تستهزئ به، فهو نازلٌ في وقته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بوعيدِ الله واستبطائه."},"action":{"text":"لا يغرّنّك تأخّرُ عقوبةِ الله فتستهزئ بوعيده، فهو نازلٌ في وقته لا يُدفع، فبادر بالتوبة."}},{"n":9,"reflection":{"text":"«ولئن أذقنا الإنسان منا رحمة ثم نزعناها منه إنه ليئوس كفور»، ولئن أذقنا الإنسانَ نعمةً منا (صحّةً أو غنًى) ثم سلبناها منه، إنه لشديدُ اليأسِ من رَوحِ الله قنوطٌ، كفورٌ لما سلف من النعمِ ناسٍ لها؛ ففي هذا ذمُّ من يقنط عند زوالِ النعمةِ ويكفر؛ فإذا زالت عنك نعمةٌ فلا تيأس من رحمةِ الله، واذكر ما بقي من نعمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اليأسِ عند زوالِ النعمة، وشكرُ الباقي منها."},"action":{"text":"إذا زالت عنك نعمةٌ فلا تيأس من رحمةِ الله ولا تنسَ سائرَ نعمه، بل اصبر واحتسب، فالفرجُ قريب."}},{"n":10,"reflection":{"text":"«ولئن أذقناه نعماء بعد ضراء مسته ليقولن ذهب السيئات عني إنه لفرح فخور»، ولئن أذقنا الإنسانَ نعمةً وسَعةً بعد شدّةٍ أصابته، ليقولنّ بطرًا: ذهبت الشدائدُ عني (ولا يشكر ولا يخاف عودها)، إنه لفرحٌ فرحَ بطرٍ فخورٌ على الناسِ بما أُوتي؛ ففي هذا ذمُّ البطرِ والفخرِ عند النعمة؛ فإذا أنعم الله عليك فاشكر ولا تبطر، واحذر الفخرَ على الناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ بلا بطرٍ ولا فخرٍ على الناس."},"action":{"text":"إذا زالت شدّتك وأقبلت نعمتك فاشكر الله ولا تبطر ولا تفخر، فالنعمةُ ابتلاءٌ كالشدّة."}},{"n":11,"reflection":{"text":"«إلا الذين صبروا وعملوا الصالحات أولئك لهم مغفرة وأجر كبير»: لكنّ الذين صبروا على الضرّاءِ فلم ييأسوا، وشكروا في السرّاءِ فلم يبطروا، وعملوا الصالحات، هؤلاء مستثنَون من تلك الطبيعةِ المذمومة؛ أولئك لهم مغفرةٌ لذنوبهم وأجرٌ كبيرٌ (الجنّة)؛ ففي هذا أنّ الصبرَ والعملَ الصالحَ يرفعان عن العبدِ ذمَّ الجزعِ والبطر؛ فتحلَّ بالصبرِ والعملِ الصالحِ تنل المغفرةَ والأجرَ الكبير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المغفرة"],"heart_state":{"text":"التحلّي بالصبرِ والعملِ الصالحِ في السرّاءِ والضرّاء."},"action":{"text":"اصبر في الشدّةِ واشكر في النعمةِ واعمل الصالحات، فبذلك تنجو من طبعِ الجزعِ والبطر، وتنال المغفرةَ والأجرَ الكبير."}}]},{"title":"تثبيتُ الرسولِ أمام تعنّتهم، وتحدّيهم بعشرِ سور","range":[12,14],"theme":"ألّا يضيق الرسولُ بتعنّتهم، وأنّ عجزهم عن المعارضةِ برهانُ صدقِ الوحي","verses":[{"n":12,"reflection":{"text":"«فلعلك تارك بعض ما يوحى إليك وضائق به صدرك أن يقولوا لولا أنزل عليه كنز أو جاء معه ملك إنما أنت نذير والله على كل شيء وكيل»: لعلّك يا محمد من شدّةِ تعنّتهم تهمُّ بترك تبليغِ بعضِ ما يُوحى إليك، ويضيق صدرك خشيةَ أن يقولوا: هلّا أُنزل عليه كنزٌ يستغني به أو جاء معه ملَكٌ يصدّقه؟ فلا تبالِ بذلك، إنما أنت نذيرٌ مبلّغٌ لا موكَّلٌ بإجابتهم، والله على كلِّ شيءٍ وكيلٌ حفيظٌ يتولّى أمرك؛ ففي هذا تسليةٌ وأمرٌ بالمضيِّ في التبليغِ رغم الأذى؛ فبلّغ الحقَّ كاملًا ولا يضق صدرك بتعنّت المعرضين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المضيُّ في تبليغِ الحقِّ كاملًا رغمَ الأذى والتعنّت."},"action":{"text":"بلّغ الحقَّ كلَّه ولا تكتم منه شيئًا خوفًا من قولِ الناس، ولا يضق صدرك بإعراضهم، فإنما عليك البلاغ."}},{"n":13,"reflection":{"text":"«أم يقولون افتراه قل فأتوا بعشر سور مثله مفتريات وادعوا من استطعتم من دون الله إن كنتم صادقين»: بل أيقولون إنّ محمدًا اختلق القرآن؟ قل لهم متحدّيًا: فأتوا بعشرِ سورٍ مثله مختلقاتٍ من عندكم (فأنتم أهلُ الفصاحة)، واستعينوا بمن قدرتم عليه من دونِ الله من الإنسِ والجنِّ إن كنتم صادقين في دعواكم أنه مفترى؛ ففي عجزهم عن عشرِ سورٍ بل عن سورةٍ برهانُ إعجازه؛ فتأمّل عجزَ البلغاءِ عنه دليلًا على أنه من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التدبّرُ في إعجازِ القرآنِ وعجزِ الفصحاءِ عن معارضته."},"action":{"text":"تأمّل عجزَ أهلِ الفصاحةِ عن الإتيانِ بمثلِ القرآن، فذاك برهانٌ قاطعٌ أنه من عند الله لا افتراء."}},{"n":14,"reflection":{"text":"«فإلم يستجيبوا لكم فاعلموا أنما أنزل بعلم الله وأن لا إله إلا هو فهل أنتم مسلمون»: فإن لم يستجب لكم المتحدَّون ولم يأتوا بمثله، فاعلموا يقينًا أنّ هذا القرآنَ إنما أُنزل بعلمِ الله لا باختلاقِ بشر، وأنه لا إله إلا هو؛ فهل أنتم منقادون مسلمون بعد قيامِ هذه الحجّة؟ ففي هذا أنّ عجزَ المعارضةِ حجّةٌ توجب الإسلام؛ فأسلم لله وانقد للحقِّ بعد وضوحِ برهانه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا إله إلا هو"],"heart_state":{"text":"الانقيادُ للحقِّ والإسلامُ لله بعد قيامِ الحجّة."},"action":{"text":"أسلم لله وانقد للحقّ، فعجزُ الخلقِ عن معارضةِ القرآنِ حجّةٌ قاطعةٌ توجب الإذعانَ والإسلام."}}]},{"title":"من أراد الدنيا وحدها خسر الآخرة","range":[15,16],"theme":"أنّ من قصد بعمله الدنيا استوفاها وحُرم الآخرة","verses":[{"n":15,"reflection":{"text":"«من كان يريد الحياة الدنيا وزينتها نوف إليهم أعمالهم فيها وهم فيها لا يبخسون»: من كان يقصد بعمله الحياةَ الدنيا وزينتها فقط لا وجهَ الله، نوفّ إليهم جزاءَ أعمالهم في الدنيا (من صحّةٍ ومالٍ ورخاء) وهم فيها لا يُنقصون شيئًا؛ ففي هذا أنّ من عمل للدنيا نالها وحدها؛ فاحذر أن تجعل الدنيا نيّةَ عملك، فتُعطاها وتُحرم الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تصحيحُ النيّةِ لله لئلا يُحبَطَ العملُ بقصدِ الدنيا."},"action":{"text":"أخلص نيّتك لله في عملك، ولا تجعل الدنيا مقصودك الأوحد، فمن أراد الدنيا بعمله نالها وحُرم أجرَ الآخرة."}},{"n":16,"reflection":{"text":"«أولئك الذين ليس لهم في الآخرة إلا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون»: أولئك الذين أرادوا الدنيا بأعمالهم ليس لهم في الآخرةِ إلا النار، وبطل ثوابُ ما صنعوا لأنهم لم يريدوا به وجهَ الله، وضاع وذهب باطلًا ما كانوا يعملون؛ ففي هذا أنّ العملَ بلا إخلاصٍ لله هباءٌ في الآخرة؛ فاجعل عملك لله وحده لئلا يحبط ويصير باطلًا يوم القيامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ لله في العملِ خشيةَ حبوطِه في الآخرة."},"action":{"text":"اعمل لله وحده لا للدنيا ولا للرياء، فالعملُ الذي لا يُراد به وجهُ الله يحبط ويصير باطلًا يوم القيامة."}}]},{"title":"من كان على بيّنةٍ من ربّه","range":[17,17],"theme":"تفاوتُ من هو على بصيرةٍ من الوحيِ عمّن يكفرُ به","verses":[{"n":17,"reflection":{"text":"«أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى إماما ورحمة أولئك يؤمنون به ومن يكفر به من الأحزاب فالنار موعده فلا تك في مرية منه إنه الحق من ربك ولكن أكثر الناس لا يؤمنون»: أفمن كان على برهانٍ ويقينٍ من ربّه (المؤمن)، ويتلو ذلك البرهانَ شاهدٌ منه (القرآنُ أو جبريلُ)، ومن قبله كتابُ موسى إمامًا يُقتدى به ورحمةً، كمن ليس كذلك؟ أولئك يؤمنون بالقرآن؛ ومن يكفر به من طوائفِ الكفرِ فالنارُ موعده؛ فلا تكن في شكٍّ منه، إنه الحقُّ من ربّك، ولكنّ أكثرَ الناسِ لا يؤمنون؛ ففي هذا أنّ صاحبَ البيّنةِ لا يستوي مع الكافر؛ فاطلب أن تكون على بيّنةٍ من ربّك، ولا تشكّ في الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ البصيرةِ واليقينِ في الدين، ونبذُ الشكّ."},"action":{"text":"اطلب أن تكون على بيّنةٍ ويقينٍ من ربّك في دينك، ولا تشكّ في الحقّ، فالقرآنُ حقٌّ من ربّك."}}]},{"title":"أظلمُ الظالمين، وخسرانُ المفترين","range":[18,22],"theme":"فضيحةُ المفترين على الله يوم القيامة، وأنهم الأخسرون","verses":[{"n":18,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أولئك يعرضون على ربهم ويقول الأشهاد هؤلاء الذين كذبوا على ربهم ألا لعنة الله على الظالمين»، ولا أحدَ أظلمُ ممّن اختلق على الله كذبًا فنسب إليه الشريكَ أو الولدَ أو حرّم ما أحلّ؛ أولئك يُعرضون على ربّهم يوم القيامةِ للحساب، ويقول الشهودُ (الملائكةُ والأنبياء) على رؤوسِ الخلائق: هؤلاء الذين كذبوا على ربّهم؛ ألا لعنةُ الله (طردُه) على الظالمين؛ ففي هذا فضيحةُ المفترين وطردُهم؛ فاحذر الكذبَ على الله، فأظلمُ الظلمِ الافتراءُ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ الشديدُ من الافتراءِ على الله فهو أظلمُ الظلم."},"action":{"text":"احذر أن تنسب إلى الله ما لم يقل، فالافتراءُ عليه أظلمُ الظلمِ وصاحبُه مفضوحٌ ملعونٌ يوم القيامة."}},{"n":19,"reflection":{"text":"«الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالآخرة هم كافرون»: هؤلاء الظالمون هم الذين يصدّون الناسَ عن دينِ الله وطاعته، ويطلبون لسبيلِ الله اعوجاجًا (يحاولون تشويهها وتنفيرَ الناسِ منها)، وهم بالآخرةِ كافرون جاحدون؛ ففي هذا أنّ الصدَّ عن سبيلِ الله وتشويهَه من أعظمِ الظلم؛ فكن داعيًا إلى سبيلِ الله لا صادًّا عنه، ولا تُشوّه دينه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى سبيلِ الله، والحذرُ من الصدِّ عنه أو تشويهه."},"action":{"text":"كن معينًا على سبيلِ الله داعيًا إليه، ولا تصدّ عنه أحدًا ولا تُشوّه دينه أو تنفّر منه."}},{"n":20,"reflection":{"text":"«أولئك لم يكونوا معجزين في الأرض وما كان لهم من دون الله من أولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون»: أولئك المفترون لم يكونوا فائتين اللهَ ولا معجزيه هربًا في الأرض، وما كان لهم من دون الله من أنصارٍ يدفعون عنهم عذابه؛ يُضاعف لهم العذابُ بكفرهم وصدّهم؛ ما كانوا يستطيعون سمعَ الحقِّ سماعَ انتفاعٍ ولا يبصرون آياتِ الله لشدّةِ إعراضهم؛ ففي هذا أنّ الإعراضَ عن الحقِّ يُصمُّ ويُعمي؛ فافتح سمعك وبصرك للحقّ لئلا تُحرمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"فتحُ السمعِ والبصرِ للحقِّ لئلا يُحرمَ العبدُ الانتفاع."},"action":{"text":"افتح قلبك وسمعك وبصرك لآياتِ الله، فالإعراضُ عن الحقِّ يُصمّ القلبَ ويُعميه عن الانتفاعِ به."}},{"n":21,"reflection":{"text":"«أولئك الذين خسروا أنفسهم وضل عنهم ما كانوا يفترون»: أولئك المفترون هم الذين خسروا أنفسهم بأن أوردوها موارِدَ الهلاك، وغاب عنهم واضمحلّ ما كانوا يختلقونه من آلهةٍ وشفعاءَ ادّعوا أنها تنفعهم؛ ففي هذا أنّ أعظمَ الخسرانِ خسرانُ النفس؛ فاحفظ نفسك من الخسرانِ بالإيمانِ والعمل، ولا تتّكل على باطلٍ يضلّ عنك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من خسرانِ النفسِ بالاتّكالِ على الباطل."},"action":{"text":"احفظ نفسك من أعظمِ الخسران (خسرانِ النفس) بالإيمانِ والعملِ الصالح، ولا تتّكل على باطلٍ يخذلك."}},{"n":22,"reflection":{"text":"«لا جرم أنهم في الآخرة هم الأخسرون»: حقًّا ولا شكَّ أنّ هؤلاء المفترين الصادّين في الآخرةِ هم أشدُّ الناسِ خسرانًا، إذ خسروا أنفسهم وأهليهم ونعيمَهم وصاروا إلى النار؛ ففي هذا تأكيدُ خسرانهم المطلق؛ فاحذر سبيلَ الأخسرين، والزم سبيلَ الرابحين بالإيمانِ والعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ خسرانِ المفترين ليجتنبَ العبدُ سبيلهم."},"action":{"text":"احذر أن تسلك سبيلَ الأخسرين (المفترين الصادّين)، والزم طريقَ الرابحين بالتوحيدِ والعملِ الصالح."}}]},{"title":"المؤمنون المخبِتون، ومثلُ الفريقين","range":[23,24],"theme":"صفةُ أهلِ الجنّةِ (الإيمانُ والعملُ والإخبات)، والفرقُ بين المؤمنِ والكافر","verses":[{"n":23,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات وأخبتوا إلى ربهم أولئك أصحاب الجنة هم فيها خالدون»: إنّ الذين آمنوا بقلوبهم، وعملوا الصالحاتِ بجوارحهم، وأخبتوا إلى ربّهم (خشعوا وخضعوا واطمأنّوا إليه وأنابوا)، أولئك أصحابُ الجنّةِ خالدون فيها؛ ففي هذا أنّ كمالَ المؤمنِ بجمعِ الإيمانِ والعملِ والإخباتِ (خشوعِ القلبِ وإنابتِه)؛ فاجمع بين إيمانِ القلبِ وعملِ الجوارحِ وإخباتِ الخشوعِ تكن من أصحابِ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["المخبتون"],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ وإخباتِ القلبِ لله."},"action":{"text":"اجمع بين الإيمانِ الصادقِ والعملِ الصالحِ وإخباتِ قلبك لله (خشوعِه وإنابته وطمأنينته)، فذاك سبيلُ أصحابِ الجنّة."}},{"n":24,"reflection":{"text":"«مثل الفريقين كالأعمى والأصم والبصير والسميع هل يستويان مثلا أفلا تذكرون»: مثَلُ الفريقين (الكافرِ والمؤمن) كمثَلِ الأعمى الأصمّ (الكافرِ الذي لا يبصر الحقَّ ولا يسمعه) والبصيرِ السميعِ (المؤمنِ الذي يبصر الآياتِ ويسمع الحقّ)، هل يستوي الفريقان؟ لا يستويان أبدًا، أفلا تتذكّرون فتعتبروا وتختاروا سبيلَ أهلِ البصرِ والسمع؟ ففي هذا أنّ المؤمنَ والكافرَ لا يستويان؛ فاختر أن تكون من أهلِ البصيرةِ السامعين للحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختيارُ سبيلِ أهلِ البصيرةِ والسمعِ للحقّ لا العمى والصمم."},"action":{"text":"كن من أهلِ البصرِ والسمعِ للحقِّ لا من العميِ الصمِّ عنه، فالمؤمنُ البصيرُ والكافرُ الأعمى لا يستويان."}}]},{"title":"نوحٌ ينذر قومَه، وردُّ الملأ المستكبرين","range":[25,31],"theme":"دعوةُ نوحٍ إلى التوحيد، واستكبارُ الملأ على أتباعه، وتواضعُ الداعية","verses":[{"n":25,"reflection":{"text":"«ولقد أرسلنا نوحا إلى قومه إني لكم نذير مبين»، ولقد أرسلنا نوحًا إلى قومه فقال لهم: إني لكم نذيرٌ بيّنُ النذارةِ من عذابِ الله إن أشركتم؛ ففي هذا بدءُ قصّةِ نوحٍ التي هي أطولُ قصصِ الأنبياءِ صبرًا؛ فاعتبر بصبرِ نوحٍ على دعوةِ قومه، وابدأ دعوتك بالإنذارِ الواضح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالأنبياءِ في وضوحِ الدعوةِ وصدقِ النذارة."},"action":{"text":"ابلّغ الحقَّ واضحًا كما فعل نوح، وأنذر من حولك من عاقبةِ الشرك، واصبر على الدعوةِ كصبرِ الأنبياء."}},{"n":26,"reflection":{"text":"«أن لا تعبدوا إلا الله إني أخاف عليكم عذاب يوم أليم»: مضمونُ إنذارِ نوح: ألّا تعبدوا إلا الله وحده لا شريك له، إني أخاف عليكم إن أشركتم عذابَ يومٍ أليمٍ موجعٍ (القيامةِ أو الطوفان)؛ ففي هذا أنّ دعوةَ كلِّ الأنبياءِ واحدةٌ: التوحيد؛ فأخلص عبادتك لله وحده كما دعت إليه الرسلُ جميعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله وحده كدعوةِ جميعِ الرسل."},"action":{"text":"اعبد الله وحده مخلصًا، فهذه دعوةُ نوحٍ وكلِّ الأنبياء، واحذر عذابَ الله بالإشراكِ به."}},{"n":27,"reflection":{"text":"«فقال الملأ الذين كفروا من قومه ما نراك إلا بشرا مثلنا وما نراك اتبعك إلا الذين هم أراذلنا بادي الرأي وما نرى لكم علينا من فضل بل نظنكم كاذبين»: فقال الأشرافُ الكافرون من قومه اعتراضًا: ما نراك إلا بشرًا مثلنا فلا مزيّةَ لك، وما اتّبعك إلا سفلتُنا وضعفاؤنا بظاهرِ الرأي بلا تفكير، وما نرى لكم علينا فضلًا يوجب اتّباعكم، بل نظنّكم كاذبين؛ فاحتقروا الرسولَ لبشريّته، واحتقروا أتباعه لفقرهم؛ ففي هذا أنّ الكِبرَ يحتقر الحقَّ وأهله؛ فلا تحتقر الحقَّ لضعفِ أتباعه، ولا تردّه لبشريّةِ من جاء به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ احتقارِ الحقِّ لضعفِ أتباعه، ونبذُ كبرِ الجاهلية."},"action":{"text":"لا تردّ الحقَّ لأنّ أتباعه ضعفاءُ أو فقراء، ولا تحتقر أحدًا لفقره، فالميزانُ عند الله بالتقوى لا بالجاه."}},{"n":28,"reflection":{"text":"«قال يا قوم أرأيتم إن كنت على بينة من ربي وآتاني رحمة من عنده فعميت عليكم أنلزمكموها وأنتم لها كارهون»: قال نوح: يا قوم أخبروني إن كنت على برهانٍ ويقينٍ من ربّي (النبوّةِ) وآتاني رحمةً من عنده (الوحيَ) فخفيت عليكم لإعراضكم، أنُكرهكم على قبولها وأنتم كارهون؟ لا نقدر على ذلك، فالهدايةُ بيدِ الله؛ ففي هذا رفقُ الداعيةِ وأنّ الإكراهَ ليس سبيلَه؛ فادعُ إلى الحقِّ برفقٍ ولا تُكره أحدًا على الهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرفقُ في الدعوةِ وتفويضُ الهدايةِ إلى الله."},"action":{"text":"ادعُ إلى الحقِّ بالرفقِ والبيان، ولا تُكره أحدًا على قبوله، فالهدايةُ بيدِ الله لا بيدِ الداعي."}},{"n":29,"reflection":{"text":"«ويا قوم لا أسألكم عليه مالا إن أجري إلا على الله وما أنا بطارد الذين آمنوا إنهم ملاقو ربهم ولكني أراكم قوما تجهلون»، ويا قوم لا أطلب منكم على الدعوةِ مالًا فتتّهموني، ما ثوابي إلا على الله، ولست بطاردٍ المؤمنين الضعفاءَ الذين احتقرتموهم كما طلبتم، فإنهم ملاقو ربّهم فيجزيهم ويكرمهم، ولكني أراكم قومًا تجهلون قدرَ هؤلاء وقدرَ الحقّ؛ ففي هذا تجرّدُ الداعيةِ عن الأجرِ وإكرامُه للمؤمنين ولو ضعفوا؛ فأكرم أهلَ الإيمانِ ولو كانوا فقراء، ولا تطلب على الحقِّ أجرًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ المؤمنين الضعفاء، وتجريدُ الدعوةِ عن الأجر."},"action":{"text":"أكرم إخوانك المؤمنين ولو كانوا ضعفاءَ فقراء، ولا تطردهم إرضاءً لأهلِ الجاه، وادعُ إلى الله محتسبًا أجرك عليه."}},{"n":30,"reflection":{"text":"«ويا قوم من ينصرني من الله إن طردتهم أفلا تذكرون»، ويا قوم من يمنعني من عقوبةِ الله إن طردتُ المؤمنين إجابةً لكم؟ لا أحد؛ أفلا تتذكّرون فتعلموا أنّ طردهم ظلمٌ يعاقب الله عليه؟ ففي هذا خوفُ نوحٍ من الله في معاملةِ الضعفاء؛ فراقب الله في معاملةِ الضعفاء، ولا تظلمهم إرضاءً لأحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في حقوقِ الضعفاءِ وعدمُ ظلمهم."},"action":{"text":"راقب الله في معاملةِ الضعفاءِ والمساكين، ولا تظلمهم أو تُقصهم إرضاءً لأصحابِ الجاهِ والمال."}},{"n":31,"reflection":{"text":"«ولا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول إني ملك ولا أقول للذين تزدري أعينكم لن يؤتيهم الله خيرا الله أعلم بما في أنفسهم إني إذا لمن الظالمين»، ولا أدّعي لكم أني أملك خزائنَ رزقِ الله، ولا أني أعلم الغيب، ولا أني ملَكٌ (بل بشرٌ رسول)، ولا أقول للذين تحتقرهم أعينكم من المؤمنين الفقراء: لن يؤتيهم الله خيرًا وثوابًا؛ الله أعلم بما في قلوبهم من الإيمانِ والخير، إني إن قلت ذلك لمن الظالمين؛ ففي هذا تواضعُ الرسولِ وإنصافُه؛ فلا تدّعِ ما ليس لك، ولا تحكم على بواطنِ الناسِ فالله أعلم بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ وتركُ ادّعاءِ ما ليس للعبد، وعدمُ الحكمِ على البواطن."},"action":{"text":"لا تدّعِ علمَ الغيبِ ولا قدرةً ليست لك، ولا تحكم على بواطنِ الناسِ ونيّاتهم، فالله وحده أعلم بما في النفوس."}}]},{"title":"تحدّي القومِ لنوح، وردُّه بتفويضِ الأمرِ لله","range":[32,35],"theme":"جدالُ المكذّبين واستعجالُهم، وأنّ الأمرَ والهدايةَ بيدِ الله","verses":[{"n":32,"reflection":{"text":"«قالوا يا نوح قد جادلتنا فأكثرت جدالنا فأتنا بما تعدنا إن كنت من الصادقين»: قال قومُ نوحٍ ملّوا الحقَّ: يا نوح قد خاصمتنا وأكثرت خصامنا، فأتنا بالعذابِ الذي تعدنا به إن كنت من الصادقين؛ فاستعجلوا العذابَ تعنّتًا وتحدّيًا؛ ففي هذا أنّ المعاندَ يملُّ الحقَّ ويستعجل ما يضرّه؛ فلا تملّ سماعَ الحقّ، ولا تستعجل عقوبةَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الملالِ من سماعِ الحقّ، وتركُ استعجالِ العقوبة."},"action":{"text":"لا تملّ من سماعِ النصحِ والحقِّ ولا تستثقله، ولا تستعجل عقوبةَ الله، بل بادر بقبولِ الحقِّ والعمل به."}},{"n":33,"reflection":{"text":"«قال إنما يأتيكم به الله إن شاء وما أنتم بمعجزين»: قال نوح: إنما يأتيكم بالعذابِ الله إن شاء في الوقتِ الذي يريده بحكمته، لا أنا، وما أنتم بفائتين اللهَ ولا معجزيه إذا أراد عذابكم؛ ففي هذا أنّ إنزالَ العذابِ بيدِ الله وحده بحكمته؛ فسلّم الأمرَ لله، ولا تظنّ أنك تفوته أو تعجزه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ الأمرِ لله، واليقينُ بأنّ العبدَ لا يُعجزه."},"action":{"text":"سلّم أمرك كلَّه لله، واعلم أنّ العقوبةَ والأمرَ بيده وحده بحكمته، وأنك لن تفوته ولن تعجزه."}},{"n":34,"reflection":{"text":"«ولا ينفعكم نصحي إن أردت أن أنصح لكم إن كان الله يريد أن يغويكم هو ربكم وإليه ترجعون»، ولا ينفعكم نصحي مهما بالغت فيه إن كان الله قد أراد إضلالكم وخذلانكم لإصراركم؛ هو ربّكم المتصرّفُ فيكم، وإليه ترجعون فيجازيكم؛ ففي هذا أنّ الهدايةَ بيدِ الله، وأنّ نفعَ النصحِ بتوفيقه؛ فاطلب من الله التوفيقَ لقبولِ النصح، وابذل النصحَ محتسبًا وإن لم يُقبل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ توفيقِ الله لقبولِ الحقّ، وبذلُ النصحِ محتسبًا."},"action":{"text":"اسأل الله أن يوفّقك لقبولِ النصحِ والحقّ، وابذل النصحَ لغيرك محتسبًا وإن لم يُقبل، فالهدايةُ بيدِ الله."}},{"n":35,"reflection":{"text":"«أم يقولون افتراه قل إن افتريته فعلي إجرامي وأنا بريء مما تجرمون»: بل أيقول كفارُ قريشٍ إنّ محمدًا اختلق هذا القرآن (أو القصص)؟ قل يا محمد: إن كنت اختلقته فعليَّ وحدي إثمُ إجرامي، وأنا بريءٌ من إجرامكم بالتكذيبِ والكفر؛ ففي هذا أنّ كلًّا يحمل تبعةَ عمله، وثقةُ الرسولِ بصدقه؛ فكن على يقينٍ من الحقّ، وابرأ من باطلِ غيرك، فكلٌّ يحمل وزره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالحقِّ والبراءةُ من باطلِ الغير، فكلٌّ يحمل وزره."},"action":{"text":"اثبت على الحقِّ بيقين، وابرأ من إجرامِ المكذّبين، واعلم أنّ كلَّ نفسٍ تحمل وزرها لا وزرَ غيرها."}}]},{"title":"وحيُ اليأسِ من قومه، وأمرُ صنعِ الفلكِ وسخريتُهم","range":[36,39],"theme":"صبرُ نوحٍ على السخرية، وأنّ عاقبةَ المستهزئين الخزيُ والعذاب","verses":[{"n":36,"reflection":{"text":"«وأوحي إلى نوح أنه لن يؤمن من قومك إلا من قد آمن فلا تبتئس بما كانوا يفعلون»، وأوحى الله إلى نوحٍ بعد طولِ الدعوةِ (٩٥٠ سنة): أنه لن يؤمن من قومك أحدٌ غيرُ من آمن، فلا تحزن ولا تغتمّ بما كانوا يفعلون من التكذيبِ والأذى؛ ففي هذا تسليةٌ للداعيةِ بعد استفراغِ الوسع؛ فابذل جهدك في الدعوة، ثم لا تحزن على من أعرض بعد البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الوسعِ في الدعوة، ثم تركُ الحزنِ على المعرضين."},"action":{"text":"ابذل غايةَ جهدك في الدعوةِ إلى الحقّ، ثم لا تحزن على من أعرض بعد البلاغ، فالهدايةُ بيدِ الله."}},{"n":37,"reflection":{"text":"«واصنع الفلك بأعيننا ووحينا ولا تخاطبني في الذين ظلموا إنهم مغرقون»، واصنع السفينةَ بمرأى منّا وحفظنا ورعايتنا، وبتعليمنا لك كيف تصنعها، ولا تراجعني في شأنِ الذين ظلموا بطلبِ إمهالهم، فقد حقّ عليهم أنهم مغرقون؛ ففي هذا رعايةُ الله لأوليائه («بأعيننا»)، وأنّ حكمَ الله في الظالمين نافذ؛ فاعمل في معيّةِ الله ورعايته، وسلّم لحكمه في الظالمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["بأعيننا"],"heart_state":{"text":"العملُ في معيّةِ الله ورعايته، والتسليمُ لحكمه."},"action":{"text":"اعمل عملك مستحضرًا رعايةَ الله لك («بأعيننا»)، وسلّم لحكمِ الله وقضائه، ولا تعترض على عدله في الظالمين."}},{"n":38,"reflection":{"text":"«ويصنع الفلك وكلما مر عليه ملأ من قومه سخروا منه قال إن تسخروا منا فإنا نسخر منكم كما تسخرون»، وشرع نوحٌ يصنع السفينةَ (في برٍّ لا ماءَ فيه)، وكلما مرّ عليه جماعةٌ من أشرافِ قومه سخروا منه واستهزؤوا، قال لهم: إن تسخروا منا اليومَ لجهلكم، فإنا نسخر منكم غدًا حين يأتي الطوفانُ فتغرقون؛ ففي هذا صبرُ نوحٍ على السخريةِ ومضيُّه في أمرِ الله؛ فلا تمنعك سخريةُ الناسِ من طاعةِ الله، وامضِ في الحقِّ ولو استهزؤوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المضيُّ في طاعةِ الله رغمَ سخريةِ الساخرين."},"action":{"text":"لا تدعك سخريةُ الناسِ تترك طاعةً أمرك الله بها، وامضِ في الحقِّ ولو استهزؤوا، فالعاقبةُ لأهلِ الحقّ."}},{"n":39,"reflection":{"text":"«فسوف تعلمون من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم»: قال نوح: فسوف تعلمون عمّا قريبٍ من يأتيه العذابُ المُذلُّ في الدنيا (الغرق)، ويحلُّ عليه العذابُ الدائمُ في الآخرة (النار)؛ ففي هذا وعيدٌ للمستهزئين بعاقبةِ سخريتهم؛ فاحذر الاستهزاءَ بالحقِّ وأهله، فعاقبةُ الساخرِ خزيٌ وعذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عاقبةِ الاستهزاءِ بالحقِّ وأهله."},"action":{"text":"احذر أن تستهزئ بالحقِّ أو بأهلِ الطاعة، فعاقبةُ المستهزئين خزيٌ في الدنيا وعذابٌ مقيمٌ في الآخرة."}}]},{"title":"مجيءُ الطوفان، وركوبُ السفينةِ باسمِ الله، ومناداةُ الابن","range":[40,43],"theme":"نجاةُ المؤمنين وابتداءُ الغرق، وأنّ لا عاصمَ من أمرِ الله إلا رحمتُه","verses":[{"n":40,"reflection":{"text":"«حتى إذا جاء أمرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول ومن آمن وما آمن معه إلا قليل»: حتى إذا جاء أمرُنا بالعذابِ ونبع الماءُ من التنّور (علامةَ بدءِ الطوفان)، قلنا لنوح: احمل في السفينةِ من كلِّ صنفٍ من الحيوانِ ذكرًا وأنثى لبقاءِ النسل، واحمل أهلك إلا من سبق عليه حكمُ الهلاكِ بكفره (كامرأتِه وابنه)، واحمل من آمن؛ وما آمن معه إلا قليلٌ رغم طولِ دعوته؛ ففي هذا أنّ أهلَ الحقِّ قد يقلّون، وأنّ النجاةَ بالإيمانِ لا بالنسب؛ فاجعل نجاتك بالإيمانِ لا بالانتسابِ إلى أحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ النجاةَ بالإيمانِ والعملِ لا بالنسبِ ولا بالكثرة."},"action":{"text":"اطلب نجاتك بالإيمانِ الصادقِ والعملِ الصالح لا بالانتسابِ إلى أحد، فالعبرةُ بالإيمانِ لا بالنسبِ ولا العدد."}},{"n":41,"reflection":{"text":"«وقال اركبوا فيها بسم الله مجراها ومرساها إن ربي لغفور رحيم»، وقال نوحٌ للمؤمنين: اركبوا في السفينةِ متوكّلين، باسمِ الله يكون جريُها على الماءِ ورسوُّها عند الرسوّ، فبذكرِ اسمه واستعانتِه تُحفظ؛ إنّ ربّي لغفورٌ لذنوبِ عباده رحيمٌ بهم إذ نجّاهم؛ ففي هذا التبرّكُ باسمِ الله والاستعانةُ به في الأمور؛ فابدأ أمورك باسمِ الله متوكّلًا عليه، راجيًا مغفرتَه ورحمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الاستعانةُ باسمِ الله والتوكّلُ عليه في كلِّ أمر."},"action":{"text":"ابدأ أعمالك باسمِ الله متوكّلًا عليه كما فعل نوح، واستعن به في مجرى أمورك ومرساها، فهو الغفورُ الرحيم."}},{"n":42,"reflection":{"text":"«وهي تجري بهم في موج كالجبال ونادى نوح ابنه وكان في معزل يا بني اركب معنا ولا تكن مع الكافرين»، والسفينةُ تجري بأهلها في موجٍ عظيمٍ كالجبالِ ارتفاعًا، ونادى نوحٌ ابنه (الكافرَ) وكان في مكانٍ منعزلٍ عنهم شفقةً عليه: يا بنيَّ اركب معنا وآمن ولا تكن مع الكافرين فتهلك؛ ففي هذا شفقةُ الأبِ ودعوتُه لولده حتى آخرِ لحظة؛ فانصح لأهلك وادعهم إلى الحقِّ ما استطعت، ولا تيأس من دعوتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشفقةُ على الأهلِ ودعوتُهم إلى الحقِّ حتى آخرِ فرصة."},"action":{"text":"انصح لأهلك وولدك وادعهم إلى الحقِّ والنجاة ما دام في العمرِ بقيّة، كما نادى نوحٌ ابنه شفقةً عليه."}},{"n":43,"reflection":{"text":"«قال سآوي إلى جبل يعصمني من الماء قال لا عاصم اليوم من أمر الله إلا من رحم وحال بينهما الموج فكان من المغرقين»: قال ابنُ نوحٍ مغترًّا بالأسباب: سأحتمي بجبلٍ يمنعني من الماء، قال نوح: لا مانعَ اليومَ من عذابِ الله وقضائه إلا من رحمه الله فعصمه؛ وحال الموجُ بين نوحٍ وابنه فكان من المغرقين الهالكين؛ ففي هذا أنّ الأسبابَ لا تعصم من قضاءِ الله، وأنّ العصمةَ برحمته وحده؛ فلا تتّكل على سببٍ دون الله، والتجئ إلى رحمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يُتّكلَ على الأسبابِ دون الله، فالعصمةُ برحمته."},"action":{"text":"لا تتّكل على قوّةٍ أو سببٍ يعصمك دون الله، فلا عاصمَ من أمره إلا رحمتُه، فالتجئ إليه واطلب عصمته."}}]},{"title":"انتهاءُ الطوفان بأمرِ الله","range":[44,44],"theme":"نفاذُ أمرِ الله في السماءِ والأرض، وبُعدُ القومِ الظالمين","verses":[{"n":44,"reflection":{"text":"«وقيل يا أرض ابلعي ماءك ويا سماء أقلعي وغيض الماء وقضي الأمر واستوت على الجودي وقيل بعدا للقوم الظالمين»، وقال الله للأرض: يا أرضُ ابلعي ماءك الذي نبع منك، وللسماء: يا سماءُ أمسكي عن المطر، فنقص الماءُ وذهب، وقُضي أمرُ الله بهلاكِ الظالمين ونجاةِ المؤمنين، واستقرّت السفينةُ على جبلِ الجوديّ، وقيل: بُعدًا وهلاكًا للقومِ الظالمين؛ ففي هذا نفاذُ أمرِ الله في الكونِ بكلمةٍ، وعظمةُ سلطانه؛ فعظّم سلطانَ الله الذي تنقاد له السماءُ والأرض، واحذر أن تكون من الظالمين المُبعَدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ سلطانِ الله النافذِ في الكون، والحذرُ من الظلم."},"action":{"text":"عظّم قدرةَ الله الذي تنقاد لأمره الأرضُ والسماءُ بكلمة، واحذر الظلمَ فعاقبةُ الظالمين البُعدُ والهلاك."}}]},{"title":"نداءُ نوحٍ في ابنه، وتأديبُ الله له","range":[45,47],"theme":"أنّ رابطةَ الإيمانِ فوق النسب، وأدبُ العبدِ ألّا يسأل ما لا علمَ له به","verses":[{"n":45,"reflection":{"text":"«ونادى نوح ربه فقال رب إن ابني من أهلي وإن وعدك الحق وأنت أحكم الحاكمين»، ونادى نوحٌ ربّه شفقةً على ابنه: ربِّ إنّ ابني من أهلي (وقد وعدتني بنجاةِ أهلي)، وإنّ وعدك الحقُّ لا يُخلَف، وأنت أحكمُ الحاكمين وأعدلُهم؛ فسأل ربّه عن حالِ ابنه راجيًا نجاته؛ ففي هذا رقّةُ الأبوّة، وأدبُ نوحٍ في سؤاله بالتفويضِ لحكمِ الله؛ فادعُ الله بأدبٍ مفوّضًا الأمرَ لحكمته، مقرًّا بأنه أحكمُ الحاكمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أحكم الحاكمين"],"heart_state":{"text":"الأدبُ في الدعاءِ والتفويضُ لحكمِ الله أحكمِ الحاكمين."},"action":{"text":"ادعُ الله في حاجاتك بأدبٍ وتفويضٍ لحكمته، مقرًّا بأنه أحكمُ الحاكمين وأعدلُهم، ولا تعترض على قضائه."}},{"n":46,"reflection":{"text":"«قال يا نوح إنه ليس من أهلك إنه عمل غير صالح فلا تسألن ما ليس لك به علم إني أعظك أن تكون من الجاهلين»: قال الله: يا نوح إنّ ابنك ليس من أهلك الذين وعدتُك بنجاتهم، لأنه كافرٌ، فقد قطعت رابطةُ الكفرِ صلةَ النسبِ في النجاة؛ إنّ سؤالك نجاتَه عملٌ غيرُ صالحٍ لا يليق، فلا تسألني ما ليس لك به علمٌ، إني أنصحك أن تكون من الجاهلين؛ ففي هذا أنّ رابطةَ الإيمانِ فوق رابطةِ الدم، وأدبُ العبدِ ألّا يسأل ما لا يعلم عاقبته؛ فلا تسأل الله إلا ما توافق فيه رضاه، واجعل ولاءك على الدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ رابطةَ الدينِ فوق النسب، وألّا يُسألَ ما لا يوافق رضا الله."},"action":{"text":"اجعل ولاءك على الإيمانِ لا على النسبِ وحده، ولا تسأل الله ما قد يخالف حكمته وحقّه، بل فوّض الأمرَ إليه."}},{"n":47,"reflection":{"text":"«قال رب إني أعوذ بك أن أسألك ما ليس لي به علم وإلا تغفر لي وترحمني أكن من الخاسرين»: قال نوحٌ مبادرًا إلى التوبة: ربِّ إني ألتجئ إليك وأعتصم بك أن أسألك ما لا علمَ لي به مما لا يوافق رضاك، وإن لم تغفر لي زلّتي وترحمني أكن من الخاسرين؛ ففي هذا سرعةُ رجوعِ الأنبياءِ إلى الله عند الزلّةِ اليسيرة، وافتقارُهم إلى مغفرته؛ فبادر بالتوبةِ والاستعاذةِ عند أدنى زلّة، واعتصم بمغفرةِ الله ورحمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"سرعةُ الرجوعِ إلى الله عند الزلّةِ والافتقارُ إلى مغفرته."},"action":{"text":"بادر بالتوبةِ والاستغفارِ عند أدنى زلّةٍ كما فعل نوح، واعتصم بمغفرةِ الله ورحمته، فبدونهما الخسران."}}]},{"title":"الهبوطُ بالسلامِ والبركة، وثمرةُ قصصِ الغيب: الصبر","range":[48,49],"theme":"سلامُ الله وبركاتُه على المؤمنين، وأنّ العاقبةَ للمتقين","verses":[{"n":48,"reflection":{"text":"«قيل يا نوح اهبط بسلام منا وبركات عليك وعلى أمم ممن معك وأمم سنمتعهم ثم يمسهم منا عذاب أليم»: قيل لنوح بعد نجاته: اهبط من السفينةِ بأمانٍ وسلامةٍ منا وبركاتٍ (خيراتٍ نامية) عليك وعلى أممٍ من ذرّيّةِ من معك من المؤمنين، وأممٌ من نسلهم سنمتّعهم في الدنيا ثم يمسّهم منا عذابٌ أليمٌ بكفرهم؛ ففي هذا أنّ السلامَ والبركةَ ثمرةُ الإيمانِ والطاعة؛ فاطلب سلامَ الله وبركاته بالإيمانِ والطاعة، فهما ثمرةُ النجاةِ الحقّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ سلامِ الله وبركاته بالإيمانِ والطاعة."},"action":{"text":"اطلب سلامَ الله وبركاته في دنياك وأخراك بالإيمانِ والطاعة، فهما ثمرةُ نجاةِ المؤمنين كما نجا نوحٌ ومن معه."}},{"n":49,"reflection":{"text":"«تلك من أنباء الغيب نوحيها إليك ما كنت تعلمها أنت ولا قومك من قبل هذا فاصبر إن العاقبة للمتقين»: تلك القصّةُ (قصّةُ نوحٍ بتفاصيلها) من أخبارِ الغيبِ التي نوحيها إليك يا محمد، ما كنت تعلمها أنت ولا قومك قبل هذا الوحي، فكونُك تخبر بها دليلُ نبوّتك؛ فاصبر على أذى قومك كما صبر نوح، إنّ العاقبةَ الحميدةَ (النصرَ والنجاة) للمتقين؛ ففي هذا تسليةٌ للنبيِّ وأنّ الصبرَ سبيلُ الظفر؛ فاصبر على طاعةِ الله وأذى الناس، فالعاقبةُ للمتقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العاقبة للمتقين"],"heart_state":{"text":"الصبرُ على الطاعةِ والأذى، واليقينُ بأنّ العاقبةَ للمتقين."},"action":{"text":"اصبر على طاعةِ الله وعلى أذى الناسِ في سبيله، كما صبر نوح، واعلم أنّ العاقبةَ الحميدةَ للمتقين."}}]},{"title":"هودٌ يدعو عادًا إلى التوحيدِ والاستغفار","range":[50,52],"theme":"دعوةُ هودٍ لقومه، وأنّ الاستغفارَ والتوبةَ سببُ الرزقِ والقوّة","verses":[{"n":50,"reflection":{"text":"«وإلى عاد أخاهم هودا قال يا قوم اعبدوا الله ما لكم من إله غيره إن أنتم إلا مفترون»، وأرسلنا إلى قومِ عادٍ أخاهم في النسبِ هودًا، فقال: يا قوم اعبدوا الله وحده، ما لكم من معبودٍ بحقٍّ غيره، ما أنتم في اتّخاذكم آلهةً معه إلا مختلقون كاذبون على الله؛ ففي هذا أنّ دعوةَ الرسلِ واحدةٌ: التوحيد، وأنّ الشركَ افتراء؛ فأفرد الله بالعبادةِ ولا تفترِ عليه بجعلِ شريكٍ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ ونبذُ الشركِ الذي هو افتراء."},"action":{"text":"اعبد الله وحده ولا تجعل له شريكًا، فدعوةُ الرسلِ جميعًا التوحيد، والشركُ افتراءٌ على الله."}},{"n":51,"reflection":{"text":"«يا قوم لا أسألكم عليه أجرا إن أجري إلا على الذي فطرني أفلا تعقلون»: يا قوم لا أطلب منكم على تبليغِ الرسالةِ أجرًا فتتّهموني، ما ثوابي إلا على الله الذي خلقني وأوجدني، أفلا تعقلون فتعلموا صدقي إذ لا أطلب نفعًا دنيويًّا؟ ففي هذا أنّ تجرّدَ الداعيةِ عن الأجرِ برهانُ صدقه؛ فادعُ إلى الحقِّ محتسبًا أجرك على الله وحده، لا على الناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في الدعوةِ واحتسابُ الأجرِ على الله وحده."},"action":{"text":"ادعُ إلى الحقِّ وأعِن عليه بلا طلبِ أجرٍ من الناس، محتسبًا ثوابك على الله الذي فطرك، فذاك أصدق."}},{"n":52,"reflection":{"text":"«ويا قوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا ويزدكم قوة إلى قوتكم ولا تتولوا مجرمين»، ويا قوم اطلبوا مغفرةَ ربّكم لما سلف، ثم توبوا إليه بالإقبالِ على طاعته، يرسل عليكم المطرَ غزيرًا متتابعًا فيُخصب أرضكم، ويزدكم قوّةً في أبدانكم وأموالكم إلى قوّتكم، ولا تُعرضوا عن دعوتي حالَ كونكم مجرمين؛ ففي هذا أنّ الاستغفارَ والتوبةَ سببٌ لسَعةِ الرزقِ والقوّة؛ فأكثر من الاستغفارِ يُوسَّع رزقك وتُمدّ بالقوّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ملازمةُ الاستغفارِ والتوبةِ لجلبِ الرزقِ والقوّة."},"action":{"text":"أكثر من الاستغفارِ والتوبةِ إلى الله، فهما سببٌ لنزولِ الرزقِ وزيادةِ القوّةِ والبركة، ولا تُعرض مجرمًا."}}]},{"title":"ردُّ عادٍ ورميُهم هودًا، وتوكّلُه على الله","range":[53,57],"theme":"إصرارُ عادٍ على الشرك، وبراءةُ هودٍ وتوكّلُه المطلقُ على ربّه","verses":[{"n":53,"reflection":{"text":"«قالوا يا هود ما جئتنا ببينة وما نحن بتاركي آلهتنا عن قولك وما نحن لك بمؤمنين»: قال قومُ عاد: يا هود ما جئتنا بحجّةٍ واضحةٍ (عنادًا وجحودًا)، وما نحن بتاركي عبادةِ آلهتنا لمجرّدِ قولك، وما نحن بمصدّقين لك؛ ففي هذا أنّ المعاندَ يجحد الحجّةَ ويتمسّك بتقليدِ الآباء؛ فلا تجحد الحقَّ بعد وضوحه، ولا تتمسّك بباطلٍ لمجرّدِ الإلف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من جحودِ الحقِّ الواضحِ والتمسّكِ بالباطلِ إلفًا."},"action":{"text":"لا تجحد الحقَّ بعد ظهورِ حجّته، ولا تتمسّك بباطلٍ ورثته أو ألفته، بل اتّبع الدليلَ حيث كان."}},{"n":54,"reflection":{"text":"«إن نقول إلا اعتراك بعض آلهتنا بسوء قال إني أشهد الله واشهدوا أني بريء مما تشركون»: ما نقول إلا إنّ بعضَ آلهتنا أصابك بجنونٍ أو سوءٍ لسبّك إيّاها فصرت تهذي! قال هود: إني أشهد الله واشهدوا أنتم أني بريءٌ ممّا تشركون به من دون الله؛ ففي هذا ثباتُ هودٍ وبراءتُه الصريحةُ من الشرك بلا مبالاةٍ بتهديدهم؛ فأعلن براءتك من الشركِ وأهله بلا خوف، وثِق بحفظِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعلانُ البراءةِ من الشركِ بثباتٍ بلا خوفٍ من أهله."},"action":{"text":"ابرأ من الشركِ وكلِّ باطلٍ بثباتٍ وصراحة، ولا تهبك تهديداتُ أهلِ الباطل، وثِق بأنّ الله حافظك."}},{"n":55,"reflection":{"text":"«من دونه فكيدوني جميعا ثم لا تنظرون»: تمّمَ هودٌ تحدّيه: فاجتمعوا أنتم وآلهتُكم التي تعبدون من دون الله على كيدي والإضرارِ بي جميعًا، ثم لا تمهلوني طرفةَ عين؛ فتحدّاهم واثقًا بأنّ آلهتَهم لا تضرّ، وأنّ الله حافظه؛ ففي هذا غايةُ التوكّلِ والثقةِ بالله؛ فمن كان الله معه فلا يخشى كيدَ الخلقِ كلِّهم، فتوكّل على الله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بحفظِ الله حتى لا يُخشى كيدُ الخلقِ مجتمعين."},"action":{"text":"توكّل على الله وثق بحفظه حتى لا تخشى كيدَ أهلِ الباطلِ ولو اجتمعوا، فمن كان الله معه لم يضرّه أحد."}},{"n":56,"reflection":{"text":"«إني توكلت على الله ربي وربكم ما من دابة إلا هو آخذ بناصيتها إن ربي على صراط مستقيم»: قال هود: إني اعتمدت على الله ربّي وربّكم المتصرّفِ في الجميع، ما من مخلوقٍ يدبُّ إلا وهو مالكٌ له قاهرٌ عليه آخذٌ بناصيته (فلا يتحرّك إلا بإذنه)، إنّ ربّي على صراطٍ مستقيمٍ في قوله وفعله، لا يظلم ولا يجور؛ ففي هذا أنّ كلَّ الخلقِ تحت قهرِ الله وقبضته؛ فتوكّل على من بيده نواصي الخلقِ كلِّهم، واطمئن إلى عدلِ ربّك واستقامةِ حكمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["آخذ بناصيتها","على صراط مستقيم"],"heart_state":{"text":"التوكّلُ على الله الذي بيده نواصي الخلق، والثقةُ بعدله."},"action":{"text":"توكّل على الله الذي يقبض على ناصيةِ كلِّ دابّة، واطمئن إلى أنّ ربّك على صراطٍ مستقيمٍ عادلٌ في كلِّ أمره."}},{"n":57,"reflection":{"text":"«فإن تولوا فقد أبلغتكم ما أرسلت به إليكم ويستخلف ربي قوما غيركم ولا تضرونه شيئا إن ربي على كل شيء حفيظ»: فإن تُعرضوا عن دعوتي فقد أدّيت ما عليّ وأبلغتكم ما أُرسلت به، وستهلكون ويستخلف ربّي قومًا غيركم في الأرض، ولا تضرّون الله بإعراضكم شيئًا، إنّ ربّي على كلِّ شيءٍ حفيظٌ رقيبٌ يحفظ أعمالكم ويجازيها؛ ففي هذا أداءُ الداعيةِ لواجبه ثم تفويضُ الأمرِ لله؛ فأدِّ واجبَ البلاغِ ثم لا تحمل همَّ الإعراض، فالله حفيظٌ على كلِّ شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحفيظ"],"heart_state":{"text":"أداءُ واجبِ البلاغِ وتفويضُ العاقبةِ إلى الله الحفيظ."},"action":{"text":"بلّغ الحقَّ وأدِّ واجبك، ثم لا يحزنك إعراضُ المعرضين، فهم لا يضرّون الله شيئًا، وهو الحفيظُ على كلِّ شيء."}}]},{"title":"نجاةُ هودٍ وأتباعِه، وهلاكُ عادٍ المعانِدة","range":[58,60],"theme":"نجاةُ المؤمنين برحمةِ الله، وعاقبةُ اتّباعِ كلِّ جبّارٍ عنيد","verses":[{"n":58,"reflection":{"text":"«ولما جاء أمرنا نجينا هودا والذين آمنوا معه برحمة منا ونجيناهم من عذاب غليظ»، ولما جاء أمرُنا بعذابِ عاد، نجّينا هودًا والذين آمنوا معه برحمةٍ منا، ونجّيناهم من العذابِ الشديدِ الغليظِ الذي أصاب قومهم (الريحَ العقيم)؛ ففي هذا أنّ رحمةَ الله تنجّي المؤمنين من عذابِ الله للظالمين؛ فالزم الإيمانَ والطاعةَ لتكون من الناجين برحمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في نجاةِ الله للمؤمنين برحمته من العذاب."},"action":{"text":"الزم الإيمانَ والطاعة، وأبشر بأنّ رحمةَ الله تنجّي المؤمنين من العذاب كما نجّت هودًا ومن معه."}},{"n":59,"reflection":{"text":"«وتلك عاد جحدوا بآيات ربهم وعصوا رسله واتبعوا أمر كل جبار عنيد»، وتلك عادٌ، كان من صفاتهم أنهم جحدوا حججَ ربّهم، وعصوا رسله (وعصيانُ رسولِهم عصيانٌ لكلِّ الرسل)، واتّبعوا أمرَ كلِّ متكبّرٍ معاندٍ للحقّ من رؤسائهم؛ ففي هذا أنّ تقليدَ الجبابرةِ في الباطلِ سببُ الهلاك؛ فلا تتّبع أمرَ متكبّرٍ معاندٍ في معصيةِ الله، واتّبع الحقَّ ودعاتَه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ المتكبّرين المعاندين في الباطل."},"action":{"text":"لا تتّبع كلَّ متسلّطٍ معاندٍ في معصيةِ الله كما فعلت عاد، بل اتّبع الحقَّ ودعاتَه، ولا تطع مخلوقًا في معصيةِ الخالق."}},{"n":60,"reflection":{"text":"«وأتبعوا في هذه الدنيا لعنة ويوم القيامة ألا إن عادا كفروا ربهم ألا بعدا لعاد قوم هود»، وأُلحق بعادٍ في الدنيا لعنةٌ (طردٌ من الرحمةِ وذكرٌ سيّئ) وكذلك يوم القيامة؛ ألا إنّ عادًا جحدوا ربّهم وكفروا نعمه، ألا بُعدًا وهلاكًا لعادٍ قومِ هودٍ؛ ففي هذا أنّ عاقبةَ الكفرِ اللعنةُ في الدارين؛ فاحذر أسبابَ اللعنةِ والبُعد، والزم شكرَ الربِّ وطاعتَه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ الذي يُتبع صاحبَه لعنةً في الدارين."},"action":{"text":"احذر جحودَ نعمِ الله وكفرَها، فعاقبةُ ذلك اللعنةُ في الدنيا والآخرة، والزم شكرَ ربّك وطاعته."}}]},{"title":"صالحٌ يدعو ثمودَ، وقربُ الله المجيب","range":[61,63],"theme":"دعوةُ صالحٍ إلى التوحيد، وأنّ الله قريبٌ مجيب، وشكُّ قومه","verses":[{"n":61,"reflection":{"text":"«وإلى ثمود أخاهم صالحا قال يا قوم اعبدوا الله ما لكم من إله غيره هو أنشأكم من الأرض واستعمركم فيها فاستغفروه ثم توبوا إليه إن ربي قريب مجيب»، وأرسلنا إلى ثمودَ أخاهم صالحًا، فقال: يا قوم اعبدوا الله وحده، ما لكم من إلهٍ غيره، هو الذي خلقكم من الأرض (من ترابها بخلقِ أبيكم آدم) وجعلكم عمّارًا لها، فاطلبوا مغفرته ثم توبوا إليه، إنّ ربّي قريبٌ من داعيه مجيبٌ لمن دعاه؛ ففي هذا أنّ من أنشأك واستعمرك في الأرضِ أحقُّ بالعبادة، وأنّ بابَ التوبةِ مفتوحٌ لقربِ الله وإجابته؛ فادعُ ربّك القريبَ المجيب، وأكثر من استغفاره وتوبته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["قريب","مجيب"],"heart_state":{"text":"الرجاءُ في قربِ الله وإجابته، وملازمةُ الاستغفارِ والتوبة."},"action":{"text":"اعبد الله الذي أنشأك واستعمرك في الأرض، وأكثر من دعائه واستغفاره وتوبته، فهو قريبٌ مجيبٌ لمن دعاه."}},{"n":62,"reflection":{"text":"«قالوا يا صالح قد كنت فينا مرجوا قبل هذا أتنهانا أن نعبد ما يعبد آباؤنا وإننا لفي شك مما تدعونا إليه مريب»: قال قومُ ثمود: يا صالحُ كنّا نرجوك ونؤمّل فيك الخيرَ والسيادةَ قبل دعوتك هذه، أتنهانا أن نعبد ما عبد آباؤنا؟ وإننا لفي شكٍّ مريبٍ (موقعٍ في الريبة) مما تدعونا إليه من التوحيد؛ ففي هذا أنّ التعصّبَ لدينِ الآباءِ حجبهم عن الحقّ، وأنهم قابلوا نصحه بالشكِّ لا التأمّل؛ فلا يصدّك تقليدُ الآباءِ عن الحقّ، ولا تقابل الحقَّ بالشكِّ بل بالتأمّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحريرُ القلبِ من تقليدِ الآباء، وتأمّلُ الحقِّ لا ردُّه بالشكّ."},"action":{"text":"لا تردّ الحقَّ تعصّبًا لدينِ الآباءِ ولا تقابله بالشكِّ المجرّد، بل تأمّل الدليلَ واتّبعه ولو خالف مألوفك."}},{"n":63,"reflection":{"text":"«قال يا قوم أرأيتم إن كنت على بينة من ربي وآتاني منه رحمة فمن ينصرني من الله إن عصيته فما تزيدونني غير تخسير»: قال صالح: يا قوم أخبروني إن كنت على برهانٍ ويقينٍ من ربّي (النبوّة) وآتاني منه رحمةً (الرسالة)، فمن يمنعني من عذابِ الله إن عصيته بترك تبليغكم وموافقتكم على الباطل؟ فما تزيدونني بدعوتكم لي إلى موافقتكم غيرَ خسارةٍ وتخسير؛ ففي هذا ثباتُ الداعيةِ على الحقِّ وخوفُه من الله في مداهنةِ الباطل؛ فلا تداهن في الحقِّ خوفًا من الناس، وخف الله في تبليغ ما أمرك به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ وعدمُ مداهنةِ الباطلِ خوفًا من الله."},"action":{"text":"لا تداهن أهلَ الباطلِ ولا توافقهم على باطلهم إرضاءً لهم، وخف الله في كتمانِ الحقِّ أو تركِ تبليغه."}}]},{"title":"ناقةُ الله آية، وعقرُها، والإمهالُ ثلاثًا","range":[64,65],"theme":"ابتلاءُ ثمودَ بالناقة، وأنّ عقرَ آيةِ الله جلب العذاب","verses":[{"n":64,"reflection":{"text":"«ويا قوم هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب قريب»، ويا قوم هذه ناقةُ الله (أخرجها من الصخرةِ آيةً بطلبكم) جعلها لكم علامةً على صدقي، فاتركوها تأكل في أرضِ الله (ولها شربُ يومٍ ولكم شربُ يوم)، ولا تصيبوها بأذًى، فإن عقرتموها أخذكم عذابٌ قريبٌ عاجل؛ ففي هذا ابتلاءٌ ظاهرٌ بامتحانِ الطاعة؛ فأطع أمرَ الله وانتهِ عن نهيه، ولا تتعدَّ حدوده فتُعاقب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"امتثالُ أمرِ الله واجتنابُ نهيه، والحذرُ من تعدّي حدوده."},"action":{"text":"أطع أمرَ الله واجتنب ما نهى عنه، ولا تتعدَّ حدوده كما فعلت ثمود، فتعدّي حدودِ الله يجلب العذاب."}},{"n":65,"reflection":{"text":"«فعقروها فقال تمتعوا في داركم ثلاثة أيام ذلك وعد غير مكذوب»: فعقروا الناقةَ عصيانًا وتحدّيًا، فقال لهم صالح: تمتّعوا في دياركم ثلاثةَ أيامٍ فقط ثم يأتيكم العذاب، ذلك وعدٌ صادقٌ لا خُلفَ فيه؛ ففي هذا أنّ الإمهالَ اليسيرَ قبل العذابِ إتمامٌ للحجّة، وأنّ وعدَ الله بالعقوبةِ حقّ؛ فلا تغترّ بمهلةٍ قصيرةٍ بعد المعصية، فوعدُ الله بالجزاءِ صادقٌ نازل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالمهلةِ بعد المعصية، فوعدُ الله صادق."},"action":{"text":"لا تغترّ بمهلةٍ يمهلك الله إيّاها بعد الذنب، وبادر بالتوبةِ فورًا، فوعدُ الله بالجزاءِ حقٌّ لا يُكذَب."}}]},{"title":"نجاةُ صالح، وهلاكُ ثمودَ بالصيحة","range":[66,68],"theme":"نجاةُ المؤمنين برحمةِ القويِّ العزيز، وأنّ عاقبةَ الظالمين الفناء","verses":[{"n":66,"reflection":{"text":"«فلما جاء أمرنا نجينا صالحا والذين آمنوا معه برحمة منا ومن خزي يومئذ إن ربك هو القوي العزيز»: فلما جاء أمرُنا بعذابِ ثمود، نجّينا صالحًا والذين آمنوا معه برحمةٍ منا، ونجّيناهم من ذلِّ ذلك اليومِ وخزيه؛ إنّ ربّك هو القويُّ الذي لا يُغالَب العزيزُ الذي لا يُرام جنابه؛ ففي هذا أنّ النجاةَ برحمةِ الله، وأنّ قوّتَه وعزّتَه فوق كلِّ قوّة؛ فالجأ إلى القويِّ العزيزِ تنجُ برحمته، ولا تخش قوّةَ الظالمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القوي","العزيز"],"heart_state":{"text":"الالتجاءُ إلى الله القويِّ العزيز، والثقةُ بنجاةِ المؤمنين."},"action":{"text":"الجأ إلى الله القويِّ العزيز، والزم الإيمانَ والطاعة، فرحمتُه تنجّي المؤمنين من خزي العذابِ وذلّه."}},{"n":67,"reflection":{"text":"«وأخذ الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين»، وأخذت الذين ظلموا أنفسهم بالكفرِ صيحةٌ عظيمةٌ (صوتٌ مهلك)، فأصبحوا في ديارهم جاثمين ميّتين هامدين على رُكبهم لا حراكَ بهم؛ ففي هذا سرعةُ أخذِ الله للظالمين بأهونِ سبب؛ فاحذر الظلمَ والكفر، فقد يأخذ الله الظالمين بغتةً بأمرٍ يسير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ فقد يأخذ الله الظالمين بغتةً."},"action":{"text":"احذر الظلمَ والكفرَ، فقد يأخذ الله الظالمين بغتةً بأهونِ سبب كما أخذ ثمودَ بالصيحة، فراقب الله في أعمالك."}},{"n":68,"reflection":{"text":"«كأن لم يغنوا فيها ألا إن ثمود كفروا ربهم ألا بعدا لثمود»: كأنّ ثمودَ لم يقيموا في ديارهم ولم يعيشوا فيها يومًا لسرعةِ زوالهم، ألا إنّ ثمودَ جحدوا ربّهم وكفروا نعمه، ألا بُعدًا وهلاكًا لثمود؛ ففي هذا أنّ عاقبةَ الكفرِ الفناءُ وكأنّ لم يكن، واللعنةُ والبُعد؛ فلا يغرّنّك تمكّنٌ في الأرض، فعاقبةُ الجاحدين أن يزولوا كأن لم يكونوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يغترَّ العبدُ بتمكّنٍ في الأرض، فعاقبةُ الكفرِ الفناء."},"action":{"text":"لا تغترّ بقوّةٍ أو تمكّنٍ في الأرض، فعاقبةُ الجاحدين أن يزولوا كأن لم يكونوا، والزم شكرَ ربّك لتبقى نعمتُه."}}]},{"title":"ضيوفُ إبراهيمَ والبُشرى بإسحاقَ ويعقوب","range":[69,73],"theme":"كرمُ إبراهيمَ لضيوفه، وبشارةُ الملائكةِ له بالذرّيّة","verses":[{"n":69,"reflection":{"text":"«ولقد جاءت رسلنا إبراهيم بالبشرى قالوا سلاما قال سلام فما لبث أن جاء بعجل حنيذ»، ولقد جاءت ملائكتُنا إبراهيمَ بالبشرى (بالولدِ وبهلاكِ قومِ لوط) في صورةِ أضياف، قالوا: سلامًا، فردّ بأحسنَ منها: سلامٌ (بالرفعِ الدالِّ على الثبات)، فما تأخّر أن جاءهم بعجلٍ سمينٍ مشويٍّ كرمًا وضيافةً بلا إبطاء؛ ففي هذا كرمُ إبراهيمَ وحسنُ ردِّ التحيّةِ وإكرامُ الضيف؛ فرُدَّ التحيّةَ بأحسنَ منها، وأكرم ضيفك بلا تكلّفٍ ولا إبطاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ الضيفِ وردُّ التحيّةِ بأحسنَ منها اقتداءً بإبراهيم."},"action":{"text":"أكرم ضيفك بما تيسّر بلا إبطاء، وردّ السلامَ بأحسنَ منه، اقتداءً بخليلِ الله إبراهيم في كرمه."},"qadiyya":{"title":"قضيّةُ سلامٍ يُردّ أبلغَ ممّا ابتُدئ","question":"قال الله: ﴿ولقد جاءت رسلنا إبراهيم بالبشرى قالوا سلامًا قال سلامٌ﴾.\nفاللفظُ واحدٌ في الموضعين، والحركةُ مختلفة: نُصب في الابتداء، ورُفع في الردّ.\nفالقضيّة: **هل في اختلاف الحركة معنًى، أم هو اتّساعٌ في العبارة؟** ثمّ: ما الذي يُؤخذ من هذا الموضع في أدب السلام؟ ثمّ: بمَ يكون الردُّ أبلغَ من الابتداء؟","background":"والمقامُ مقامُ ضيافة: قومٌ داخلون، ومضيفٌ يستقبل؛ فالابتداءُ منهم والردُّ منه.\nولا يظهر أثرُ الحركة حتى نستحضر أصلًا في اللسان: أنّ الفعل يدلّ على الحدوث والتجدّد، وأنّ الاسم يدلّ على الثبوت.\nفالجملةُ الفعليّة تُخبر عن أمرٍ يقع مرّةً بعد مرّة، والجملةُ الاسميّة تُخبر عن أمرٍ قارٍّ لا يتقيّد بزمان.\nو﴿سلامًا﴾ منصوب، ونصبُه على تقدير فعلٍ ينصبه؛ فآل إلى جملةٍ فعليّة. و﴿سلامٌ﴾ مرفوع، ورفعُه على الابتداء أو الخبر؛ فآل إلى جملةٍ اسميّة.\nفصار الفرقُ بين التسليمين فرقًا بين بابين من أبواب الكلام، لا فرقَ حركةٍ عارضة.","what_happened":"فسّر السعديُّ الرسل بأنّهم «من الملائكة الكرام»، وفسّر البشرى بأنّها «بالبشارة بالولد، حين أرسلهم الله لإهلاك قوم لوط، وأمرهم أن يمروا على إبراهيم، فيبشروه بإسحاق».\nثمّ فسّر التسليمين تفسيرًا مختصرًا: «سلموا عليه، ورد عليهم السلام».\n⭐ ثمّ استخرج من ذلك أحكامًا، فقال: «ففي هذا مشروعية السلام، وأنه لم يزل من ملة إبراهيم عليه السلام»، ثمّ «وأن السلام قبل الكلام»، ثمّ «وأنه ينبغي أن يكون الرد، أبلغ من الابتداء».\n⭐ **ثمّ علّل الأخير منها بعلّةٍ نحويّة، ولم يدَعه وصيّةً مرسلة**: «لأن سلامهم بالجملة الفعلية، الدالة على التجدد، ورده بالجملة الاسمية، الدالة على الثبوت والاستمرار، وبينهما فرق كبير كما هو معلوم في علم العربية».\nثمّ رجع إلى سياق الضيافة، ففسّر ﴿فما لبث﴾ بأنّه «إبراهيم لما دخلوا عليه»، وفسّر ﴿أن جاء بعجل حنيذ﴾ بقوله: «بادر لبيته، فاستحضر لأضيافه عجلا مشويا على الرضف سمينا، فقربه إليهم فقال: ألا تأكلون؟».","the_verdict":"فالحاصلُ أنّ الأدب ها هنا مأخوذٌ من حركةٍ لا من موعظة.\nولمّا كان الفرقُ بين البابين مقرَّرًا في العربيّة، دلّ اختلافُ التسليمين على أنّ الردّ ليس مثلَ الابتداء؛ فهي حركةٌ حاملةٌ لمعنًى، لا اتّساعٌ في العبارة.\n⭐ وموضعُ الدقّة أنّه لم يستحسن الزيادة استحسانًا، بل ردّها إلى فرقٍ مقرّرٍ في العربيّة، فقال: «وبينهما فرق كبير كما هو معلوم في علم العربية». **فصار الحكمُ مبنيًّا على دلالةٍ تُراجَع، لا على ذوقٍ يُنازَع.**\n⭐ وأمّا بمَ يكون الردُّ أبلغ، فالذي دلّ عليه لفظُه أنّ البلاغة في جهة الدلالة: سلامُهم بالجملة الفعليّة فهو حدثٌ يتجدّد، وردُّه بالجملة الاسميّة فهو إثباتٌ يستقرّ. فالزيادةُ زيادةُ تقريرٍ أوّلًا، والزيادةُ في مبنى اللفظ إلحاقٌ منّا بهذا الأصل.\n⭐ وأمّا الذي يُؤخذ في أدب السلام فقد صدّر أحكامه بمشروعيّة السلام، وبأنّه لم يزل من ملّة إبراهيم عليه السلام؛ فهو أدبٌ متّصلٌ في المِلل قبل أن يكون أدبًا في هذه.\nوموضعُ الغلط عند من لم ينتبه اثنان: الأوّل أن يُسوّي بين الابتداء والردّ فيردّ بمثل ما سُلّم عليه، وقد قال هو «أبلغ من الابتداء». والثاني أن يجعل السلام تابعًا للكلام فيبدأ بحاجته، وقد قال «وأن السلام قبل الكلام»؛ وهذا مأخوذٌ من حكمه الآخر في السياق نفسه، لا من اختلاف الحركة.\nوقد قال «ينبغي» ولم يزد؛ فهو أدبٌ يُطلب، ولا نحمله على أكثرَ ممّا قال.","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: زِد في ردّك على ما ابتُدئتَ به.** فإن سُلّم عليك فلا تقتصر على مثل لفظه؛ فالمساواةُ ها هنا وقوفٌ دون ما ندب إليه، إذ قال «أبلغ من الابتداء»، ولم يقل مثله. وعلامتُه: أن تستعيد آخر ردٍّ رددتَه اليوم، فإن كان طبقَ ما قيل لك فلم تَزِد.\n**والثاني: قدّم السلام على حاجتك.** في الدخول، وفي المكالمة، وفي الرسالة المكتوبة. فإن وجدتَ أوّلَ سطرٍ كتبتَه اليوم طلبًا لا سلامًا فقد قلبتَ الترتيب.\n**والثالث: أتبِع السلام بالإكرام قبل أن تُسأل.** فقد بادر الخليلُ إلى بيته فجاء بالعجل ثمّ عرضه عليهم. وعلامتُه: أن يكون أوّلُ ما تعرضه على الداخل شيئًا قدّمتَه، لا سؤالًا سألتَه.","grade":"ma'thur","source":"تفسيرُ السعديّ للرسل («من الملائكة الكرام»)، وللبشرى («بالبشارة بالولد»)، وللتسليمين («سلموا عليه، ورد عليهم السلام»)، وما استخرجه من ذلك («ففي هذا مشروعية السلام»، و«وأن السلام قبل الكلام»، و«وأنه ينبغي أن يكون الرد»)، وتعليلُه النحويّ («لأن سلامهم بالجملة الفعلية»)، وتفسيرُه ﴿فما لبث﴾ («إبراهيم لما دخلوا عليه») و﴿أن جاء بعجل حنيذ﴾ («بادر لبيته»): كلُّها بنصّها في تفسير السعديّ (١١:٦٩).","honesty":"وممّا يجب أن يُقال:\nتقريرُنا في التمهيد أنّ نصب ﴿سلامًا﴾ على تقدير فعل، وأنّ رفع ﴿سلامٌ﴾ على الابتداء أو الخبر، تمهيدٌ منّا لبيان وجه الجملتين؛ والإمامُ إنّما ذكر أنّ سلامهم بالجملة الفعليّة وردَّه بالجملة الاسميّة، ولم يتعرّض لإعراب اللفظين. وكذلك تقريرُنا أنّ الفعل للتجدّد والاسم للثبوت، بسطٌ منّا لما أحال هو فيه على علم العربيّة.\nوقولُنا إنّ البلاغة ها هنا في جهة الدلالة أوّلًا، استنباطٌ منّا من تعليله؛ وإلحاقُنا الزيادةَ في مبنى اللفظ بذلك إلحاقٌ منّا لم يذكره، وعليه بُني البندُ الأوّل ممّا نخرج به.\nوموضعا الغلط ترتيبٌ منّا على كلامه المجموع، وإن كان الحكمان اللذان بُنيا عليهما من لفظه.\nوالأمثلةُ من المكالمة والرسالة المكتوبة أمثلةٌ منّا، وكذلك موازينُ الاختبار التي اقترحناها.\nوأخذُنا من قصّة العجل أدبًا في تعجيل القِرى، استنباطٌ منّا من حكايته لفعل الخليل، ولم يَسُقه هو حكمًا.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":70,"reflection":{"text":"«فلما رأى أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة قالوا لا تخف إنا أرسلنا إلى قوم لوط»: فلما رأى إبراهيمُ أيديَ ضيوفه لا تمتدُّ إلى الطعامِ ولا يأكلون، أنكرهم وأحسّ في نفسه خوفًا منهم (ظنّهم يريدون سوءًا)؛ قالوا: لا تخف إنّا ملائكةٌ أُرسلنا إلى قومِ لوطٍ لإهلاكهم؛ ففي هذا أنّ امتناعَ الضيفِ عن الطعامِ يورث الريبة، وأنّ الملائكةَ طمأنته؛ فادفع الخوفَ باليقينِ بالله، واطمئن إلى أنّ رسلَ الله لا يأتون بشرّ لأوليائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ الخوفِ بالطمأنينةِ إلى أنّ أمرَ الله خيرٌ لأوليائه."},"action":{"text":"إذا خفت من أمرٍ فاطمئن إلى لطفِ الله بأوليائه، فما جاء الملائكةُ إبراهيمَ إلا بخيرٍ رغمَ خوفه أوّلًا."}},{"n":71,"reflection":{"text":"«وامرأته قائمة فضحكت فبشرناها بإسحاق ومن وراء إسحاق يعقوب»، وامرأتُه (سارة) قائمةٌ تخدم الضيوف، فضحكت سرورًا (أو تعجّبًا من غفلةِ قومِ لوطٍ عن العذابِ النازلِ بهم)، فبشّرناها على ألسنةِ الملائكةِ بأنها ستلد إسحاق، ومن بعدِ إسحاقَ ستُرزق حفيدًا هو يعقوب؛ ففي هذا بشارةٌ بذرّيّةٍ صالحةٍ مباركة؛ فأبشر بأنّ الله يرزق الصالحين ذرّيّةً طيّبةً ولو بعد اليأسِ من الأسباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في فضلِ الله بالذرّيّةِ الصالحةِ ولو بعد اليأس."},"action":{"text":"ارجُ فضلَ الله في كلِّ أمرٍ ولو انقطعت الأسباب، فقد بشّر سارةَ بالولدِ والحفيدِ وهي عجوز، ولا ييأس مؤمنٌ من رَوحِ الله."}},{"n":72,"reflection":{"text":"«قالت يا ويلتى أألد وأنا عجوز وهذا بعلي شيخا إن هذا لشيء عجيب»: قالت سارةُ متعجّبةً: يا عجبًا! أألِدُ وأنا عجوزٌ كبيرةٌ، وهذا زوجي شيخٌ كبير؟ إنّ ولادةً من مثلنا لشيءٌ عجيبٌ في العادة؛ ففي هذا تعجّبُها من خرقِ العادةِ لا شكًّا في قدرةِ الله؛ فاعلم أنّ قدرةَ الله لا تحدّها عادةٌ ولا سببٌ، فما استعصى على العادةِ هيّنٌ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ قدرةَ الله لا تحدّها عادةٌ ولا سبب."},"action":{"text":"أيقن أنّ قدرةَ الله فوق العاداتِ والأسباب، فما تراه مستحيلًا في العادةِ هيّنٌ على الله إذا أراده."}},{"n":73,"reflection":{"text":"«قالوا أتعجبين من أمر الله رحمت الله وبركاته عليكم أهل البيت إنه حميد مجيد»: قالت الملائكةُ لسارة: أتعجبين من قضاءِ الله وقدرته؟ فقدرتُه لا يُعجبُ منها، رحمةُ الله وبركاتُه (خيراتُه المتّصلة) عليكم يا أهلَ بيتِ النبوّة، إنه حميدٌ محمودٌ في أفعاله مجيدٌ عظيمُ الكرمِ والشرف؛ ففي هذا أنّ فضلَ الله على أهلِ بيتِ النبوّةِ عظيم، وأنّ قدرتَه لا يُتعجَّب منها؛ فاطلب رحمةَ الله وبركاته، ولا تستعظم على قدرةِ الله شيئًا، فهو الحميدُ المجيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الحميد","المجيد"],"heart_state":{"text":"طلبُ رحمةِ الله وبركاته، وإجلالُ قدرتِه فلا يُستعظمُ عليها شيء."},"action":{"text":"اطلب رحمةَ الله وبركاته على بيتك وأهلك، ولا تستعظم على قدرةِ الله أمرًا، فهو الحميدُ المجيدُ ذو الفضلِ والكرم."}}]},{"title":"مجادلةُ إبراهيمَ في قومِ لوط، وحلمُه","range":[74,76],"theme":"شفقةُ إبراهيمَ ومراجعتُه رجاءَ رفعِ العذاب، وأنّ أمرَ الله ماضٍ","verses":[{"n":74,"reflection":{"text":"«فلما ذهب عن إبراهيم الروع وجاءته البشرى يجادلنا في قوم لوط»: فلما زال عن إبراهيمَ الخوفُ الذي أحسّه، وجاءته البشرى بالولد، أخذ يجادل رسلَنا (الملائكة) في شأنِ قومِ لوطٍ راجيًا تأخيرَ العذابِ عنهم رحمةً وشفقة (لعلّ فيهم من يؤمن)؛ ففي هذا رحمةُ إبراهيمَ حتى بالعصاة، ورجاؤه هدايتهم؛ فتخلّق برحمةِ إبراهيمَ، واحرص على نجاةِ الناسِ ولو كانوا عصاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرحمةُ بالخلقِ والحرصُ على نجاتهم ولو كانوا عصاة."},"action":{"text":"تخلّق برحمةِ إبراهيم، واحرص على هدايةِ الناسِ ونجاتهم ولو كانوا مذنبين، وادعُ لهم بالهدايةِ لا بالهلاك."}},{"n":75,"reflection":{"text":"«إن إبراهيم لحليم أواه منيب»: إنّ إبراهيمَ لحليمٌ لا يعجل بالعقوبةِ ويصبر على الأذى، أوّاهٌ كثيرُ التأوّهِ والدعاءِ والخشيةِ لله، منيبٌ رجّاعٌ إلى الله في أموره كلِّها؛ ففي هذا مدحُ الله لإبراهيمَ بثلاثِ خصالٍ جليلة؛ فتخلّق بالحلمِ والرقّةِ والإنابةِ إلى الله، فتلك صفاتُ الخليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["حليم","أواه","منيب"],"heart_state":{"text":"التخلّقُ بالحلمِ والرقّةِ والإنابةِ إلى الله."},"action":{"text":"تحلَّ بالحلمِ فلا تعجل بالانتقام، وبرقّةِ القلبِ وكثرةِ الدعاء، وبالإنابةِ إلى الله، فتلك صفاتُ إبراهيمَ الخليل."}},{"n":76,"reflection":{"text":"«يا إبراهيم أعرض عن هذا إنه قد جاء أمر ربك وإنهم آتيهم عذاب غير مردود»: قالت الملائكةُ: يا إبراهيمُ أعرض عن هذا الجدالِ في شأنهم، فقد نفذ أمرُ ربّك بهلاكهم، وإنهم آتيهم عذابٌ لا يُردُّ ولا يُدفع لاستحقاقهم؛ ففي هذا أنّ الشفاعةَ لا تنفع بعد نفوذِ قضاءِ الله في المستحقّين؛ فسلّم لحكمِ الله وقضائه إذا نفذ، فأمرُه ماضٍ لا يُردّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لقضاءِ الله إذا نفذ، فأمرُه ماضٍ لا يُردّ."},"action":{"text":"سلّم لقضاءِ الله وحكمته إذا نفذ أمرُه في المستحقّين، فأمرُه ماضٍ لا يُردّ، وارضَ بعدله."}}]},{"title":"ضيوفُ لوطٍ وكربُه، ومراودةُ قومه","range":[77,80],"theme":"شدّةُ ما لقيه لوطٌ من قومه، وعجزُ الداعيةِ الذي يطلب ركنًا شديدًا","verses":[{"n":77,"reflection":{"text":"«ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب»، ولما جاءت ملائكتُنا لوطًا في صورةِ شبابٍ حِسان، حزن لمجيئهم وضاق صدرُه بهم خوفًا عليهم من قومه (ولم يعلم أنهم ملائكة)، وقال: هذا يومٌ شديدٌ عصيبُ الكرب؛ ففي هذا شدّةُ ما كان يعانيه لوطٌ من فسادِ قومه، وغيرتُه على ضيوفه؛ فاستشعر كربَ الأنبياءِ في الغيرةِ على الحقِّ والحرمات، والزم الغيرةَ على محارمِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الغيرةُ على حرماتِ الله، واستشعارُ كربِ الدعاةِ في الفساد."},"action":{"text":"كن غيورًا على حرماتِ الله ومحارمه، واستشعر كربَ الأنبياءِ من الفساد، واعمل على إنكارِ المنكرِ ما استطعت."}},{"n":78,"reflection":{"text":"«وجاءه قومه يهرعون إليه ومن قبل كانوا يعملون السيئات قال يا قوم هؤلاء بناتي هن أطهر لكم فاتقوا الله ولا تخزون في ضيفي أليس منكم رجل رشيد»، وجاء قومُ لوطٍ يُسرعون إليه طمعًا في ضيوفه لفعلِ الفاحشة، وكانوا من قبلُ معتادين على الفواحش؛ قال لهم لوط: يا قوم هؤلاء بناتي (نساءُ أمّتي، أو بناتُه) فتزوّجوهنّ فهنّ أطهرُ لكم من الحرام، فاتّقوا الله ولا تفضحوني في ضيفي، أليس فيكم رجلٌ واحدٌ رشيدٌ يأمر بالمعروفِ وينهى عن المنكر؟ ففي هذا دفعُ لوطٍ الفاحشةَ بالحلالِ وتذكيرُه بالله؛ فادفع المنكرَ بالحلالِ البديل، وذكّر الناسَ بتقوى الله وحفظِ الحرمات.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ المنكرِ بالبديلِ الحلال، والتذكيرُ بتقوى الله."},"action":{"text":"ادفع المنكرَ ما استطعت، ودُلَّ الناسَ على الحلالِ بديلًا عن الحرام، وذكّرهم بتقوى الله وصونِ الحرمات."}},{"n":79,"reflection":{"text":"«قالوا لقد علمت ما لنا في بناتك من حق وإنك لتعلم ما نريد»: قال قومُ لوطٍ مصرّين على فجورهم: لقد علمت أنه لا رغبةَ لنا ولا حاجةَ في نسائنا (بناتك)، وإنك لتعلم ما نريد من الفاحشةِ بالرجال؛ ففي هذا تصريحُهم بالإصرارِ على الباطلِ ورفضِ الحلال؛ فاحذر أن يبلغ بك اتّباعُ الشهوةِ أن ترفض الحلالَ وتصرّ على الحرام، فذاك منتهى الانتكاس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من انتكاسِ الفطرةِ برفضِ الحلالِ والإصرارِ على الحرام."},"action":{"text":"احذر أن تنتكس فطرتك فترغب في الحرامِ وتزهد في الحلال، والزم الطهرَ وصون نفسك عن كلِّ فاحشة."}},{"n":80,"reflection":{"text":"«قال لو أن لي بكم قوة أو آوي إلى ركن شديد»: قال لوطٌ متمنّيًا: لو أنّ لي بكم قوّةً من الأتباعِ والأنصارِ أدفعكم بها، أو أنضمّ إلى عشيرةٍ منيعةٍ تمنعني، لدفعتكم عن ضيفي؛ ففي هذا غايةُ ما يلقاه الداعيةُ الغريبُ من الضعفِ ظاهرًا، وتمنّيه المنعة؛ وقد قال النبيُّ ﷺ: «رحمةُ الله على لوطٍ، كان يأوي إلى ركنٍ شديد» (يعني الله)؛ فالجأ إلى الله فهو الركنُ الشديدُ الذي لا يُغلَب، ولا تيأس عند ضعفِ الأسباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتجاءُ إلى الله الركنِ الشديدِ عند ضعفِ الأسباب."},"action":{"text":"إذا ضعفت أسبابك واشتدّ كربك فالجأ إلى الله فهو الركنُ الشديدُ الذي لا يُغلَب، ولا تيأس من نصره وعونه."}}]},{"title":"طمأنةُ الملائكةِ للوط، وهلاكُ قومه","range":[81,83],"theme":"نجاةُ لوطٍ وأهله، وقلبُ قريةِ الفاحشةِ وإمطارُها بالحجارة","verses":[{"n":81,"reflection":{"text":"«قالوا يا لوط إنا رسل ربك لن يصلوا إليك فأسر بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك إنه مصيبها ما أصابهم إن موعدهم الصبح أليس الصبح بقريب»: قالت الملائكةُ: يا لوطُ إنا رسلُ ربّك أُرسلنا لإهلاكهم، لن يصلوا إليك بسوء، فسر بأهلك في جزءٍ من آخرِ الليل، ولا يلتفت منكم أحدٌ إلى ما وراءه، إلا امرأتك (الخائنة) فإنه مصيبها ما أصابهم لأنها منهم قلبًا؛ إنّ موعدَ هلاكهم الصبح، أليس الصبحُ بقريب؟ ففي هذا نجاةُ لوطٍ بطاعةِ أمرِ الله، وهلاكُ امرأتِه بخيانتها؛ فالنجاةُ بالإيمانِ والطاعةِ لا بالقرابة، والزم أمرَ الله في وقتِ الشدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ النجاةَ بالإيمانِ والطاعةِ لا بالقرابةِ ولا النسب."},"action":{"text":"الزم طاعةَ الله وأمرَه في وقتِ الشدّة، واعلم أنّ النجاةَ بالإيمانِ لا بالقرابة، فامرأةُ لوطٍ هلكت بخيانتها."}},{"n":82,"reflection":{"text":"«فلما جاء أمرنا جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل منضود»: فلما جاء أمرُنا بعذابِ قومِ لوط، قلبنا قريتهم فجعلنا أعلاها أسفلها، وأمطرنا عليها حجارةً من طينٍ متحجّرٍ (سِجّيل) متتابعٍ بعضُه إثرَ بعض؛ ففي هذا شدّةُ عقوبةِ الله لأهلِ الفاحشة، وأنّ عاقبةَ المجاهرةِ بالفواحشِ الاستئصال؛ فاحذر الفواحشَ والمجاهرةَ بها، فعقوبةُ الله لأهلها شديدة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الفواحشِ والمجاهرةِ بها، فعقوبةُ الله شديدة."},"action":{"text":"احذر الفواحشَ كلَّها والمجاهرةَ بالمعاصي، فعاقبةُ من استحلّها الاستئصالُ، كما قُلبت قريةُ قومِ لوطٍ وأُمطرت بالحجارة."}},{"n":83,"reflection":{"text":"«مسومة عند ربك وما هي من الظالمين ببعيد»: تلك الحجارةُ معلَّمةٌ مُعدّةٌ عند ربّك لعذابهم، كلُّ حجرٍ لمن قُدّر له؛ وما هذه العقوبةُ من الظالمين ببعيدةٍ، أي أنها قريبةٌ ممّن يظلم ويعصي في كلِّ زمان؛ ففي هذا تخويفٌ لكلِّ ظالمٍ أن تصيبه سنّةُ الله في الظالمين؛ فاحذر الظلمَ والمعصية، فعقوبةُ الله ليست بعيدةً عمّن سلك سبيلَ الظالمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ العبدِ أن تناله سنّةُ الله في الظالمين إن ظلم."},"action":{"text":"احذر الظلمَ والمعاصي، واعلم أنّ عقوبةَ الله ليست ببعيدةٍ عن الظالمين، فراقب الله واجتنب سبيلهم."}}]},{"title":"شعيبٌ يدعو مدينَ إلى التوحيدِ والوفاءِ في الكيل","range":[84,86],"theme":"دعوةُ شعيبٍ إلى العدلِ في المعاملة، وأنّ بقيّةَ الله (الحلال) خيرٌ من الحرام","verses":[{"n":84,"reflection":{"text":"«وإلى مدين أخاهم شعيبا قال يا قوم اعبدوا الله ما لكم من إله غيره ولا تنقصوا المكيال والميزان إني أراكم بخير وإني أخاف عليكم عذاب يوم محيط»، وأرسلنا إلى أهلِ مدينَ أخاهم شعيبًا، فقال: يا قوم اعبدوا الله وحده، ولا تنقصوا الناسَ في الكيلِ والوزنِ عند البيعِ والشراء، إني أراكم في سَعةٍ ونعمةٍ فلا تحوجكم إلى بخسِ الناس، وإني أخاف عليكم عذابَ يومٍ يحيط بكم فلا مفرَّ منه؛ ففي هذا أنّ الدينَ توحيدٌ ومعاملةٌ عادلة، وأنّ النعمةَ تُشكَر لا تُقابَل بالطمع؛ فأخلص العبادةَ لله واعدل في معاملتك، ولا يحملك الطمعُ على بخسِ الناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين توحيدِ الله والعدلِ في المعاملةِ المالية."},"action":{"text":"اعبد الله وحده، واعدل في بيعك وشرائك، ولا تنقص الناسَ حقوقهم، ولا يدفعك الطمعُ إلى الغشِّ والبخس."}},{"n":85,"reflection":{"text":"«ويا قوم أوفوا المكيال والميزان بالقسط ولا تبخسوا الناس أشياءهم ولا تعثوا في الأرض مفسدين»، ويا قوم أتمّوا الكيلَ والوزنَ بالعدلِ التامّ ولا تنقصوهما، ولا تنقصوا الناسَ حقوقهم وأشياءهم، ولا تسعوا في الأرضِ بالفسادِ والظلمِ والإخافة؛ ففي هذا أمرٌ بالعدلِ ونهيٌ عن البخسِ والإفساد؛ فأوفِ الحقوقَ كاملةً، ولا تنقص أحدًا شيئًا، ولا تكن سببًا لفسادٍ في الأرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالحقوقِ كاملةً، والحذرُ من البخسِ والإفساد."},"action":{"text":"أوفِ الناسَ حقوقهم كاملةً في كلِّ معاملة، ولا تبخسهم شيئًا، ولا تسعَ بفسادٍ في الأرض بظلمٍ أو غشّ."}},{"n":86,"reflection":{"text":"«بقية الله خير لكم إن كنتم مؤمنين وما أنا عليكم بحفيظ»: ما يبقيه الله لكم من الحلالِ بعد إيفاءِ الحقوقِ خيرٌ لكم من الحرامِ الذي تجمعونه بالبخس، إن كنتم مؤمنين حقًّا؛ ولست أنا عليكم برقيبٍ أحصي أعمالكم، إنما الله هو الرقيب؛ ففي هذا أنّ القليلَ الحلالَ خيرٌ من الكثيرِ الحرام، وأنّ البركةَ في الحلال؛ فارضَ بالحلالِ ولو قلّ، فهو خيرٌ وأبقى من حرامٍ كثير.","source":"تفسير السعدي","grade":"ma'thur"},"names":["بقية الله"],"heart_state":{"text":"إيثارُ الحلالِ القليلِ على الحرامِ الكثير طلبًا للبركة."},"action":{"text":"ارضَ بالكسبِ الحلالِ ولو قلّ، فبقيّةُ الله (الحلال) خيرٌ وأبرك من مالٍ حرامٍ كثير، والبركةُ في الطيّب."}}]},{"title":"ردُّ قومِ شعيب، وجوابُه بالإصلاحِ والتوكّل","range":[87,90],"theme":"استهزاءُ القومِ بدعوته، وأنّ غايةَ الداعيةِ الإصلاحُ بتوفيقِ الله","verses":[{"n":87,"reflection":{"text":"«قالوا يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء إنك لأنت الحليم الرشيد»: قال قومُ شعيبٍ استهزاءً: يا شعيبُ أصلاتُك التي تصلّيها تأمرك أن ندع عبادةَ آلهةِ آبائنا، أو أن نترك التصرّفَ في أموالنا كما نشاء (بالبخسِ والتطفيف)؟! إنك لأنت الحليمُ الرشيد (قالوها تهكّمًا)؛ ففي هذا استهزاؤهم بالصلاةِ وبالحقّ، وتعلّقُهم بتقليدِ الآباءِ وحبِّ المال؛ فلا يصدّك تقليدُ الآباءِ ولا حبُّ المالِ عن الحقّ، ولا تستهزئ بشعائرِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ شعائرِ الله، ونبذُ تقليدِ الآباءِ وحبِّ المالِ إذا خالفا الحق."},"action":{"text":"عظّم الصلاةَ وشعائرَ الله، ولا تستهزئ بشيءٍ منها، ولا يمنعك تقليدُ الآباءِ ولا حبُّ المالِ من اتّباعِ الحق."},"qadiyya":{"title":"قضيّةُ كلامٍ خرج تهكّمًا فصحّ تقريرًا","question":"قال الله عن قوم شعيبٍ: ﴿قالوا يا شعيبُ أصلاتُك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء إنّك لأنت الحليم الرشيد﴾.\nوظاهرُ آخره ثناءٌ، ومرادُهم به الشتم. وقد حكى اللهُ لفظَهم كما خرج منهم.\nفالقضيّة: ما الذي أرادوه بهذا الكلام؟ ثمّ: ما الذي صنعه الإمامُ به بعد أن بيّن مرادهم؟ ثمّ: كيف يصحّ الكلامُ الواحد على غير وجه قائله؟","background":"ولا يستبين هذا حتى يُفرّق بين شيئين في الكلام:\n**مدلولُ اللفظ، وقصدُ المتكلّم به.**\nفالتهكّمُ أن يُخرج المتكلّمُ لفظَه على صورة المدح وهو يريد ضدّه؛ فيتوجّه الهزءُ إلى قصده، ويبقى اللفظُ على دلالته.\nوحالُ القوم أنّهم جمعوا أمرين نهاهم عنهما نبيّهم: عبادةَ غير الله، ونقصَ المكيال والميزان. وكانوا يرون في اتّباع آبائهم عقلًا. فردّوا النهي عنهما جميعًا بجملةٍ واحدة.","what_happened":"**بدأ السعديُّ ببيان وجه كلامهم**: «أي: قالوا ذلك على وجه التهكم بنبيهم، والاستبعاد لإجابتهم له».\nثمّ بسط معناه، فقال إنّهم أرادوا: «أنه لا موجب لنهيك لنا، إلا أنك تصلي لله, وتتعبد له»، وأنّ متابعته تركٌ لآبائهم: «لقول ليس عليه دليل إلا أنه موافق لك، فكيف نتبعك، ونترك آباءنا الأقدمين أولي العقول والألباب؟!».\nثمّ ذكر ما نهاهم عنه في المال: «من وفاء الكيل، والميزان، وأداء الحقوق الواجبة فيها»، وجوابَهم عنه: «بل لا نزال نفعل فيها ما شئنا، لأنها أموالنا، فليس لك فيها تصرف».\nثمّ فسّر ﴿إنّك لأنت الحليم الرشيد﴾ على مرادهم لا على ظاهره: «أي: أئنك أنت الذي، الحلم والوقار، لك خلق، والرشد لك سجية، فلا يصدر عنك إلا رشد، ولا تأمر إلا برشد، ولا تنهى إلا عن غي، أي: ليس الأمر كذلك».\nثمّ صرّح بقصدهم، وكشف المقابلة التي عقدوها: «وقصدهم أنه موصوف بعكس هذين الوصفين: بالسفه والغواية، أي: أن المعنى: كيف تكون أنت الحليم الرشيد، وآباؤنا هم السفهاء الغاوون؟!!».\n⭐ **ثمّ انعطف على الكلام نفسِه فأثبته**: «وهذا القول الذي أخرجوه بصيغة التهكم، وأن الأمر بعكسه, ليس كما ظنوه، بل الأمر كما قالوه».\nثمّ قرّره جزءًا جزءًا: «إن صلاته تأمره أن ينهاهم، عما كان يعبد آباؤهم الضالون، وأن يفعلوا في أموالهم ما يشاءون، فإن الصلاة تنهى عن الفحشاء والمنكر».\n⭐ **ثمّ ختم بأنّ ما نُهوا عنه أكبرُ الفحشاء**: «وأي فحشاء ومنكر، أكبر من عبادة غير الله، ومن منع حقوق عباد الله، أو سرقتها بالمكاييل والموازين، وهو عليه الصلاة والسلام الحليم الرشيد».","the_verdict":"فالحاصلُ أنّه **لم يدفع كلامهم، بل أقرّه ونزع عنه قصدهم**.\nوإنّما صحّ لأنّ الهزء كان في المراد، والصدق في اللفظ؛ فلمّا سقط قصدُهم بقي لفظُهم يشهد عليهم. وهذا جوابُ السؤال الثالث: أنّ قصد المتكلّم لا يُغيّر مدلول عبارته.\n⭐ **وموضعُ الدقّة أنّهم عقدوا في هزئهم ربطًا بين صلاته ونهيه**، فأثبت الإمامُ صدق هذا الربط، فقال: «إن صلاته تأمره أن ينهاهم»، وعلّله بما في الصلاة من النهي عن الفحشاء والمنكر.\nفبقيت في كلامهم دعاوى، أشدُّها إضمارًا: أنّ ما نُهوا عنه ليس بفحشاء ولا منكر. وهذه هي التي ردّها في آخر كلامه، فقابل جملتهم بجزأيها: قالوا ﴿ما يعبد آباؤنا﴾ فقابله بعبادة غير الله، وقالوا ﴿أن نفعل في أموالنا ما نشاء﴾ فقابله بمنع حقوق العباد وسرقتها بالمكاييل.\nوأمّا دعواهم في الملك: «لأنها أموالنا، فليس لك فيها تصرف»، فيردُّها ما حكاه عن نهيه؛ إذ جعله أمرًا بـ«أداء الحقوق الواجبة فيها». فالمالُ الذي فيه حقٌّ واجب ليس ملكًا خالصًا.\nوأمّا دعواهم في الآباء فقد حكى عنهم أنّهم «أولي العقول والألباب»، ثمّ سمّاهم عند التقرير «آباؤهم الضالون»، وأثبت لنبيّهم في آخره الحلمَ والرشد؛ فانتقضت المقابلةُ التي عقدوها من طرفيها.\nوأمّا الغلطُ عند من لم ينتبه **فأن يُحسب ذكرُ الصلاة في كلامهم فضلةً**، وهو موضع الحجّة منه؛ إذ ربطوا هم بين صلاته ونهيه، فأُخذوا بربطهم.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: **إذا هُزئ بك في دينك فاعزل اللفظ عن القصد.** اكتب العبارة كما قيلت، ثمّ اسأل: أهي صحيحةٌ في نفسها؟ فإن كانت فأقرّها ولا تعتذر منها، ودع قصد قائلها عليه.\nوالثاني: **اختبر صلاتك بما انتهيتَ عنه.** انظر في هذا الأسبوع: ما المنكرُ الواحد الذي تركتَه لأجل أنّك تصلّي؟ فإن لم تجد جوابًا معيّنًا فالنظرُ في صلاتك أولى من النظر في عددها.\nوالثالث: **حرّر حقّ الناس في مالك.** خذ بابًا من كسبك تأخذ فيه فوق حقّك أو تعطي دون الحقّ، في وزنٍ أو أجرةٍ أو ساعةِ عمل، فردّه إلى العدل قبل أن ينقضي الشهر.","grade":"ma'thur","source":"تفسيرُ السعديّ لوجه قولهم («أي: قالوا ذلك على وجه التهكم بنبيهم»)، وبسطُه لمعنى كلامهم («أنه لا موجب لنهيك لنا») واحتجاجِهم بآبائهم («فكيف نتبعك، ونترك آباءنا الأقدمين») وما نُهوا عنه في المال («من وفاء الكيل، والميزان») ودعواهم فيه («بل لا نزال نفعل فيها ما شئنا»)، وتفسيرُه ﴿إنّك لأنت الحليم الرشيد﴾ على مرادهم («أي: أئنك أنت الذي، الحلم والوقار») وتصريحُه بقصدهم («وقصدهم أنه موصوف بعكس هذين الوصفين»)، ثمّ إثباتُه للكلام («وهذا القول الذي أخرجوه بصيغة التهكم») وتقريرُه إيّاه («إن صلاته تأمره أن ينهاهم») وختامُه («وأي فحشاء ومنكر، أكبر من عبادة غير الله»): كلُّها بنصّها في تفسير السعديّ (١١:٨٧).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين مدلول اللفظ وقصد المتكلّم، وتعريفُنا التهكّم، تمهيدٌ منّا لتقريب صنيع الإمام؛ وليس نصًّا له.\nوتسميتُنا ما عقدوه ربطًا بين صلاته ونهيه، وتسميتُنا ما بقي في كلامهم دعاوى، وتوزيعُنا ردَّ كلٍّ منها على موضعه، وقولُنا إنّه قابل جملتهم بجزأيها وإنّ المقابلة انتقضت من طرفيها: ترتيبٌ منّا على كلامه المجموع وملاحظةٌ على لفظه؛ وهو لم يُسمِّ ذلك ولا رتّبه.\nوأمّا نفيُنا الملكَ الخالص عمّا فيه حقٌّ لغير مالكه فمبنيٌّ منّا على قوله «أداء الحقوق الواجبة فيها»؛ وقد ساقه في بسط كلامهم لا في تحرير معنى الملك.\nوقولُنا إنّ لفظهم بقي شاهدًا عليهم، استنباطٌ منّا من قوله إنّ الأمر كما قالوه.\nوأمّا ما أوصينا به من إقرار اللفظ الصحيح وترك الاعتذار منه، ومن اختبار الصلاة بما انتُهي عنه وتقديمِ النظر فيها على عدّها، والأمثلةُ في الوزن والأجرة وساعة العمل، فتخريجٌ منّا وأمثلةٌ منّا؛ ولم ينصّ الإمامُ على شيء منها. ومن رأى أنّا وسّعنا فليردّه."}},{"n":88,"reflection":{"text":"«قال يا قوم أرأيتم إن كنت على بينة من ربي ورزقني منه رزقا حسنا وما أريد أن أخالفكم إلى ما أنهاكم عنه إن أريد إلا الإصلاح ما استطعت وما توفيقي إلا بالله عليه توكلت وإليه أنيب»: قال شعيب: يا قوم أخبروني إن كنت على برهانٍ من ربّي ورزقني رزقًا حلالًا حسنًا (فكيف أدعوكم إلى باطل؟)، وما أريد أن أنهاكم عن شيءٍ ثم أفعله أنا مخالفًا لكم (فأكون كذّابًا)، ما أريد إلا إصلاحكم بقدرِ استطاعتي، وما توفيقي لذلك إلا بالله، عليه وحده توكّلت وإليه أرجع في أموري؛ ففي هذا أنّ الداعيةَ الصادقَ يبدأ بنفسه ولا يخالف قولَه فعلُه، وأنّ التوفيقَ بالله؛ فليكن قصدك الإصلاح، وابدأ بنفسك، وعلّق توفيقك بالله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ما توفيقي إلا بالله"],"heart_state":{"text":"قصدُ الإصلاحِ وموافقةُ الفعلِ للقول، وتعليقُ التوفيقِ بالله."},"action":{"text":"اقصد الإصلاحَ بقدرِ استطاعتك، وابدأ بنفسك فلا تنهَ عن أمرٍ وتأتيه، وعلّق توفيقك بالله متوكّلًا عليه منيبًا إليه."}},{"n":89,"reflection":{"text":"«ويا قوم لا يجرمنكم شقاقي أن يصيبكم مثل ما أصاب قوم نوح أو قوم هود أو قوم صالح وما قوم لوط منكم ببعيد»، ويا قوم لا يحملنّكم خلافي وعداوتي على الإصرارِ فيصيبكم من العذابِ مثلُ ما أصاب قومَ نوحٍ أو هودٍ أو صالح، وما قومُ لوطٍ منكم ببعيدٍ زمانًا ولا مكانًا فاعتبروا بهم؛ ففي هذا تخويفٌ لهم بمصارعِ الأممِ ودعوةٌ للاعتبار؛ فاعتبر بمصارعِ الأممِ قبلك، ولا تحملك عداوةُ أحدٍ للحقِّ على ردّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأمم، وألّا تحمل العداوةُ على ردِّ الحق."},"action":{"text":"اعتبر بعاقبةِ الأممِ المكذّبة، ولا يحملنّك بغضُك لأحدٍ أو خلافُك معه على ردِّ الحقِّ الذي جاء به."}},{"n":90,"reflection":{"text":"«واستغفروا ربكم ثم توبوا إليه إن ربي رحيم ودود»، واطلبوا مغفرةَ ربّكم لما سلف من ذنوبكم، ثم ارجعوا إليه بالطاعةِ والإنابة، إنّ ربّي رحيمٌ واسعُ الرحمةِ بعباده، ودودٌ يحبّ التوّابين ويتودّد إليهم بالإحسان؛ ففي هذا أنّ بابَ التوبةِ مفتوحٌ لسَعةِ رحمةِ الله ومحبّتِه للتائبين؛ فأكثر من الاستغفارِ والتوبة، وأبشر بأنّ ربّك رحيمٌ يحبّك إذا أنبت إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحيم","الودود"],"heart_state":{"text":"الرجاءُ في رحمةِ الله وودّه للتائبين، وملازمةُ التوبة."},"action":{"text":"أكثر من الاستغفارِ والتوبةِ إلى الله، وأبشر بأنّ ربّك رحيمٌ ودودٌ يحبّ التوّابين ويتودّد إليهم بالإحسان."}}]},{"title":"تهديدُ القومِ لشعيب، وثباتُه وتفويضُه","range":[91,93],"theme":"استضعافُ القومِ للداعية، وأنّ العزّةَ بالله لا بالعشيرة","verses":[{"n":91,"reflection":{"text":"«قالوا يا شعيب ما نفقه كثيرا مما تقول وإنا لنراك فينا ضعيفا ولولا رهطك لرجمناك وما أنت علينا بعزيز»: قال قومُ شعيب: يا شعيبُ ما نفهم كثيرًا مما تقول (إعراضًا وتجاهلًا)، وإنا لنراك فينا ضعيفًا لا منعةَ لك (كان ضعيفَ البصرِ أو قليلَ الأتباع)، ولولا احترامُنا لعشيرتك (رهطك) لقتلناك رجمًا، وما أنت عندنا بعزيزٍ نهابك؛ ففي هذا استخفافُهم بالحقِّ وأهله، واعتدادُهم بالقوّةِ والعصبيّة؛ فلا تستضعف صاحبَ الحقّ، ولا تجعل العصبيّةَ ميزانَ التقدير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استضعافِ أهلِ الحقّ، ونبذُ ميزانِ العصبيّة."},"action":{"text":"لا تحتقر صاحبَ الحقِّ لضعفه أو قلّةِ ناصره، ولا تجعل العصبيّةَ والقوّةَ ميزانك، فالعزّةُ بالحقِّ لا بالعشيرة."}},{"n":92,"reflection":{"text":"«قال يا قوم أرهطي أعز عليكم من الله واتخذتموه وراءكم ظهريا إن ربي بما تعملون محيط»: قال شعيب: يا قوم أعشيرتي أعزُّ عندكم وأهيبُ من الله حتى تركتم أذاي من أجلهم لا من أجلِ الله، وجعلتم الله وراء ظهوركم منبوذًا لا تراقبونه؟! إنّ ربّي بما تعملون محيطٌ علمًا وقدرةً فيجازيكم؛ ففي هذا إنكارُ أن تُقدَّم مهابةُ الخلقِ على مهابةِ الله؛ فاجعل مهابةَ الله في قلبك فوق مهابةِ الخلق، وراقبه في السرِّ والعلن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ مهابةِ الله على مهابةِ الخلق، ومراقبتُه المحيط."},"action":{"text":"اجعل خشيةَ الله في قلبك فوق خشيةِ الناس، ولا تنبذ أمره وراء ظهرك مراعاةً لأحد، فالله محيطٌ بعملك."}},{"n":93,"reflection":{"text":"«ويا قوم اعملوا على مكانتكم إني عامل سوف تعلمون من يأتيه عذاب يخزيه ومن هو كاذب وارتقبوا إني معكم رقيب»، ويا قوم اعملوا على طريقتكم وحالِكم التي أنتم عليها فإني عاملٌ على طريقتي، سوف تعلمون من يأتيه العذابُ المُخزي ومن هو الكاذبُ منّا؛ وانتظروا عاقبةَ الأمرِ إني معكم منتظرٌ مراقب؛ ففي هذا تهديدٌ وثقةٌ من شعيبٍ بأنّ العاقبةَ له؛ فاثبت على طريقِ الحقِّ واثقًا بأنّ العاقبةَ لأهله، وانتظر نصرَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على طريقِ الحقِّ والثقةُ بأنّ العاقبةَ لأهله."},"action":{"text":"اثبت على طريقِ الحقِّ واعمل عليه، واثق بأنّ العاقبةَ لأهله لا لأهلِ الباطل، وانتظر وعدَ الله وهو خيرُ منتظَر."}}]},{"title":"نجاةُ شعيب، وهلاكُ مدينَ بالصيحة","range":[94,95],"theme":"نجاةُ المؤمنين برحمةِ الله، وأنّ عاقبةَ الظالمين الفناءُ والبُعد","verses":[{"n":94,"reflection":{"text":"«ولما جاء أمرنا نجينا شعيبا والذين آمنوا معه برحمة منا وأخذت الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين»، ولما جاء أمرُنا بعذابِ مدين، نجّينا شعيبًا والذين آمنوا معه برحمةٍ منا، وأخذت الذين ظلموا أنفسهم بالكفرِ والبخسِ صيحةٌ عظيمةٌ (وأخذَتْهم رجفةٌ وظُلّةٌ في مواضعَ أخرى)، فأصبحوا في ديارهم ميّتين هامدين على رُكبهم؛ ففي هذا أنّ رحمةَ الله تنجّي المؤمنين وأنّ عذابه يأخذ الظالمين؛ فالزم الإيمانَ والعدلَ لتكون من الناجين برحمةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في نجاةِ الله للمؤمنين، والحذرُ من عاقبةِ الظلم."},"action":{"text":"الزم الإيمانَ والعدلَ في معاملتك، وأبشر برحمةِ الله التي تنجّي المؤمنين، واحذر أن تلقى عاقبةَ الظالمين."}},{"n":95,"reflection":{"text":"«كأن لم يغنوا فيها ألا بعدا لمدين كما بعدت ثمود»: كأنّ أهلَ مدينَ لم يقيموا في ديارهم ولم يتنعّموا فيها لسرعةِ زوالهم واستئصالهم، ألا بُعدًا وهلاكًا لمدينَ من رحمةِ الله كما بَعِدت ثمودُ قبلهم؛ ففي هذا أنّ عاقبةَ الظلمِ الفناءُ التامُّ واللعنة؛ فلا تغترّ بنعمةٍ أو تمكّن، والزم شكرَ الله وعدلَه لتبقى في نعمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يغترَّ العبدُ بنعمةٍ أو تمكّن، فعاقبةُ الظلمِ الفناء."},"action":{"text":"لا تغترّ بما أنت فيه من نعمةٍ وتمكّن، والزم شكرَ الله وعدلَه، فعاقبةُ الظالمين أن يزولوا كأن لم يكونوا."},"qadiyya":{"title":"قضيّةُ المكيال: ذنبٌ يُعدّ صغيرًا في العرف، وقد أُهلكت به أمّة","question":"أرسل اللهُ شعيبًا عليه السلام إلى مدين، فدعاهم إلى أمرين: التوحيد، وإيفاء المكيال والميزان.\nفإن قيل: وما شأن الكيل والوزن حتى **يُقرن بالتوحيد في دعوة نبيّ**، ويُجعل سببًا لهلاك أمّة؟\nفقد قال الله في خاتمة القصّة: «كأن لم يغنَوا فيها، ألا بُعدًا لمدينَ كما بعدت ثمود».\nوقد استخرج الإمامُ السعديُّ من هذه القصّة ثلاثَ عشرةَ فائدة، أكثرُها في المال وكسبه.\nفالقضيّة: **لماذا كان نقصُ الكيل بهذه المنزلة؟** وما الذي يُستفاد منه اليوم وقد كثرت وسائلُ الأخذ؟","background":"ولا يُفهم هذا حتى نعرف ما «الكيل» و«الوزن» في ذلك الزمان من الصفر:\nلم تكن هناك آلاتُ قياسٍ مضبوطة، بل كان البيعُ بالمكيال والميزان اليدويّين، و**الغشُّ فيهما سهلٌ خفيّ**: أن يُوفي حين يأخذ ويُنقص حين يُعطي.\nفهو أخذُ مالٍ بغير حقّ، ولكن في صورةٍ لا يُسمّى فيها سرقة؛ فالبائعُ لم يمدّ يدَه إلى جيب أحد.\nوهذا هو موضعُ الخطر: معصيةٌ **يُعدّها العرفُ من الشطارة**، ويُسمّيها القرآنُ من أسباب الهلاك.","what_happened":"عقد السعديُّ في خاتمة القصّة فصلًا، فذكر فيه من الفوائد:\nأوّلًا: أنّ الشرائع تدخل في المحاسبة كما يدخل الأصل: «أنّ الكفّار، كما يُعاقبون ويُخاطبون بأصل الإسلام، فكذلك بشرائعه وفروعه»، واستدلّ بأنّ شعيبًا دعاهم إلى التوحيد وإلى إيفاء المكيال والميزان، «وجعل الوعيدَ مرتّبًا على مجموع ذلك».\nثمّ سمّى الذنبَ باسمه: «أنّ نقص المكاييل والموازين من كبائر الذنوب، وتُخشى العقوبةُ العاجلة على من تعاطى ذلك، وأنّ ذلك من سرقة أموال الناس».\n⭐ ثمّ استعمل **قياسًا من الأدنى إلى الأعلى**: «وإذا كان سرقتُهم في المكاييل والموازين موجبةً للوعيد، فسرقتُهم على وجه القهر والغلبة من باب أولى وأحرى».\nفإذا كان الأخذُ الخفيُّ بهذه المنزلة، **فالأخذُ بالقوّة والسلطان أشدّ**.\nثمّ قرّر قاعدةً في الجزاء: «أنّ الجزاء من جنس العمل، فمن بخس أموالَ الناس يريد زيادةَ ماله، عوقب بنقيض ذلك»، وكان ذلك **سببًا لزوال الخير الذي عنده**، واستدلّ بقول شعيب ﴿إنّي أراكم بخير﴾.\nثمّ في القناعة: «أنّ على العبد أن يقنع بما آتاه الله، ويقنع بالحلال عن الحرام، وبالمكاسب المباحة عن المكاسب المحرّمة»، واستدلّ بقوله ﴿بقيّةُ الله خيرٌ لكم﴾، وذكر أنّ في الحلال «من البركة وزيادة الرزق ما ليس في التكالب على الأسباب المحرّمة من المحق وضدّ البركة».\n**ثمّ ربط ذلك بالإيمان نفسِه**: «أنّ ذلك من لوازم الإيمان وآثاره، فإنّه رتّب العملَ به على وجود الإيمان، فدلّ على أنّه إذا لم يوجد العملُ، فالإيمانُ ناقصٌ أو معدوم».\nثمّ في حقيقة الملك: أنّ المال الذي يرزقه اللهُ الإنسانَ، وإن خوّله إيّاه، «فليس له أن يصنع فيه ما يشاء، فإنّه أمانةٌ عنده».\nوختم بفائدةٍ في الدعوة: «أنّ من تكملة دعوة الداعي وتمامها أن يكون أوّلَ مبادرٍ لما يأمر غيرَه به».","the_verdict":"فالحاصلُ أنّ الذنب **لم يُهوَّن لأنّه خفيّ**، ولم يُصغَّر لأنّ مقاديره صغيرة.\n⭐ وأمّا القياسُ الذي استعمله السعديُّ فينبغي أن يُتأمّل: «فسرقتُهم على وجه القهر والغلبة من باب أولى وأحرى».\nفقد فتح باب النظر من الأدنى إلى الأعلى: إذا كان الغشُّ في مثقالٍ يوجب الوعيد، فما بالُ الأخذ بالقوّة والسلطان والحيلة؟ **والناسُ يستعظمون السرقةَ الظاهرةَ ويستهينون بالخفيّة**؛ والقرآنُ أهلك أمّةً بالخفيّة.\nوأمّا قاعدةُ «الجزاء من جنس العمل» فقد نزّلها على المال بعينه: **أنّ من بخس ليزيد مالُه، عوقب بنقيض قصده**. فالبخسُ الذي أُريد به الزيادةُ يكون سببَ الزوال. وحجّتُه من الآية: أنّ شعيبًا قال لهم ﴿إنّي أراكم بخير﴾ أي: في سعةٍ ونعمة، فلا تسعوا في زوالها بفعلكم.\n⭐ وأثقلُ ما في الفصل ربطُه هذا بالإيمان: «فإنّه رتّب العملَ به على وجود الإيمان، فدلّ على أنّه إذا لم يوجد العملُ، فالإيمانُ ناقصٌ أو معدوم». **فجعل الأمانةَ في الكسب علامةً على الإيمان لا فرعًا عليه**.\nوأمّا قولُه إنّ المال «أمانةٌ عنده» فيقطع دعوى الاستقلال بالملك: فليس لأحدٍ أن يقول: مالي أفعل فيه ما أشاء. **إنّما هو مستخلَفٌ فيه، والمستخلَفُ يُسأل**.\nوأمّا خاتمةُ الفصل ففيها ميزانٌ للداعي: أن يكون أوّلَ من يبادر إلى ما يأمر به. وهذا هو الذي فعله شعيبٌ حين قال ﴿وما أريد أن أخالفكم إلى ما أنهاكم عنه﴾.","for_you":"فأمّا الذي تخرج به فأربعة:\nالأوّل: انظر في كسبك من الباب الخفيّ لا الظاهر. فأنت لا تسرق، ولكن: أتُوفي العملَ الذي تُؤجر عليه؟ أتصف السلعةَ بما فيها؟ أتُخبر بالعيب؟ أتحسب الساعاتِ التي لم تعمل فيها؟ فهذه كلُّها من بابٍ واحد: **أن تأخذ ما ليس لك في صورةٍ لا تُسمّى سرقة**.\nوالثاني: إذا استعظمتَ ذنبًا واستصغرتَ آخر فقس بميزان الإمام. **فإن كان الأدنى موجبًا للوعيد فالأعلى أولى**. والناسُ يعكسون: يستعظمون ما تُنكره الأعرافُ ويستهينون بما تتسامح فيه.\nوالثالث: إذا رأيتَ في مالك محقًا وأنت لا تدري سببَه فراجع مدخله. فقد جعل الإمامُ البخسَ سببًا لزوال الخير. وربّ رجلٍ يستكثر ويستزيد ثمّ لا يجد بركةً؛ **وعلّتُه في مدخل ماله لا في مقداره**.\nوالرابع، وهو للداعي والمعلّم والأب: **كن أوّلَ من يبادر لما تأمر به**. فقد جعله الإمامُ من «تكملة دعوة الداعي وتمامها». والذي يأمر بما لا يفعل يُبطل دعوتَه بيده، ولا يحتاج خصمُه إلى حجّة.","grade":"ma'thur","source":"فصلُ الفوائد في تفسير السعديّ (١١:٩٥): قولُه «أن الكفار، كما يعاقبون، ويخاطبون، بأصل الإسلام, فكذلك بشرائعه وفروعه»، و«ومنها: أن نقص المكاييل والموازين، من كبائر الذنوب, وتخشى العقوبة العاجلة، على من تعاطى ذلك، وأن ذلك من سرقة أموال الناس»، و«وإذا كان سرقتهم في المكاييل والموازين، موجبة للوعيد، فسرقتهم على وجه القهر والغلبة من باب أولى وأحرى»، و«ومنها: أن الجزاء من جنس العمل، فمن بخس أموال الناس، يريد زيادة ماله، عوقب بنقيض ذلك»، و«ومنها: أن على العبد أن يقنع بما آتاه الله، ويقنع بالحلال عن الحرام»، و«ومنها: أن ذلك، من لوازم الإيمان وآثاره، فإنه رتب العمل به, على وجود الإيمان، فدل على أنه إذا لم يوجد العمل، فالإيمان ناقص أو معدوم»، و«فليس له أن يصنع فيه ما يشاء، فإنه أمانة عنده»، و«ومنها: أن من تكملة دعوة الداعي وتمامها أن يكون أول مبادر لما يأمر غيره به»: كلُّها بنصّها.","honesty":"وممّا يجب أن يُقال:\n**عدُّ الفوائد ثلاثَ عشرةَ من عملنا نحن**، وقد عددناها في نصّ السعديّ؛ ولم نستوعبها، وإنّما نقلنا منها ما يخدم مسألتنا. ومن أرادها كلَّها فهي في تفسيره في هذا الموضع، وهو معنا في تبويب التفاسير.\nوأمّا وصفُنا لحال الكيل والوزن قبل آلات القياس، فمعلومٌ بالعادة، ولم ننقله عن أحدٍ من الستّة ها هنا بلفظه.\nوأمّا الأمثلةُ التي ضربناها في تنزيل المعنى (إتقانُ العمل المأجور عليه، ووصفُ السلعة، والإخبارُ بالعيب) فمن صنيعنا تقريبًا للمعنى، و**ليست منصوصةً في كلام الإمام** ها هنا؛ ومن رأى أنّا وسّعنا فليردّه.\nوأمّا مسألةُ زيادة الإيمان ونقصانه وحكمُ تارك العمل على وجهها ففي كتب الاعتقاد، ولم نتعرّض لها؛ وإنّما نقلنا لفظ السعديّ في موضعه."}}]},{"title":"موسى وفرعون، وسوءُ قيادةِ أهلِ الباطل","range":[96,99],"theme":"إرسالُ موسى بالآيات، وأنّ متبوعي الباطلِ يقودون أتباعهم إلى النار","verses":[{"n":96,"reflection":{"text":"«ولقد أرسلنا موسى بآياتنا وسلطان مبين»، ولقد أرسلنا موسى بآياتنا الدالّةِ على صدقه (كالعصا واليدِ والآياتِ التسع) وبحجّةٍ واضحةٍ قاهرةٍ لا تُدفع؛ ففي هذا أنّ الله يؤيّد رسله بالبراهينِ القاطعة؛ فأيقن أنّ الله يؤيّد الحقَّ بالحجّةِ والبرهان، واطلب الحقَّ بدليله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يؤيّد الحقَّ بالحجّةِ والبرهان."},"action":{"text":"أيقن أنّ الله يؤيّد رسله والحقَّ بالبراهينِ القاطعة، واطلب الحقَّ ببرهانه، ولا تتّبع إلا ما قام عليه الدليل."}},{"n":97,"reflection":{"text":"«إلى فرعون وملئه فاتبعوا أمر فرعون وما أمر فرعون برشيد»: أرسلنا موسى إلى فرعونَ وأشرافِ قومه، فاتّبع الأشرافُ والعامّةُ أمرَ فرعونَ في الكفرِ والتكذيب، وما أمرُ فرعونَ برشيدٍ ولا صوابٍ بل غيٌّ وضلال؛ ففي هذا أنّ تقليدَ المتبوعِ في الضلالِ لا يعذر التابع؛ فلا تتّبع أحدًا في باطلٍ ولو كان كبيرًا مطاعًا، وزِن أمرَ المتبوعِ بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ اتّباعِ المتبوعِ في الباطلِ ولو كان كبيرًا مطاعًا."},"action":{"text":"لا تتّبع أحدًا في باطلٍ ولو كان ذا سلطانٍ أو جاه، وزِن كلَّ أمرٍ يُدعى إليه بميزانِ الحقّ، فأمرُ الظالمِ غيرُ رشيد."}},{"n":98,"reflection":{"text":"«يقدم قومه يوم القيامة فأوردهم النار وبئس الورد المورود»: يتقدّم فرعونُ قومَه يوم القيامةِ (كما تقدّمهم في الضلالِ في الدنيا) فيقودهم إلى النارِ فيدخلهموها، وبئس المكانُ الذي يَرِدونه؛ ففي هذا أنّ قائدَ الضلالِ يقود أتباعه إلى الهلاك، وأنّ رئاسةَ الباطلِ خزيٌ ووبال؛ فاحذر أن تكون قدوةً في باطلٍ أو تابعًا لقدوةِ سوءٍ إلى النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يكون العبدُ قدوةً في باطلٍ أو تابعًا لقدوةِ سوء."},"action":{"text":"احذر أن تدعو إلى باطلٍ فتقود غيرك إلى النار، أو تتّبع قدوةَ سوءٍ إليها، واجعل قدوتك من يقودك إلى الجنّة."}},{"n":99,"reflection":{"text":"«وأتبعوا في هذه لعنة ويوم القيامة بئس الرفد المرفود»، وأُلحق بفرعونَ وقومه في الدنيا لعنةٌ (بالغرقِ والذكرِ السيّئ) وكذلك يوم القيامةِ لعنةٌ أخرى؛ بئس العطاءُ المُعطى الذي أُعطوه: لعنةٌ في الدنيا ولعنةٌ في الآخرة؛ ففي هذا أنّ عاقبةَ أئمّةِ الكفرِ اللعنةُ المضاعفةُ في الدارين؛ فاحذر سبيلَ فرعونَ وأتباعه، والزم سبيلَ الموحّدين لتنال رحمةَ الله لا لعنته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من سبيلٍ عاقبتُه اللعنةُ في الدارين."},"action":{"text":"احذر أن تسلك سبيلَ أهلِ الكفرِ والظلم، فعاقبتُه اللعنةُ في الدنيا والآخرة، والزم سبيلَ الموحّدين لتنال الرحمة."}}]},{"title":"عبرةُ القرى، وأنّ الله لم يظلمهم","range":[100,102],"theme":"أنّ هلاكَ الأممِ بظلمِ أنفسهم، وأنّ آلهتهم لم تُغنِ عنهم شيئًا","verses":[{"n":100,"reflection":{"text":"«ذلك من أنباء القرى نقصه عليك منها قائم وحصيد»: ذلك الذي قصصناه عليك من أخبارِ القرى المهلكة نقصّه عليك يا محمد للعبرة، منها ما هو قائمٌ باقٍ أثرُه، ومنها ما هو حصيدٌ مُستأصَلٌ عافٍ لا أثرَ له كالزرعِ المحصود؛ ففي هذا أنّ آثارَ الأممِ عبرةٌ للمعتبرين؛ فاعتبر بمصارعِ الأممِ وآثارها، وسل نفسك: أين هم بعد قوّتهم؟","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ الأممِ ومصارعها."},"action":{"text":"اعتبر بأخبارِ الأممِ الهالكةِ وآثارها، وتذكّر كيف زالت قوّتُهم، لتحذر سبيلهم وتلزم طريقَ الناجين."}},{"n":101,"reflection":{"text":"«وما ظلمناهم ولكن ظلموا أنفسهم فما أغنت عنهم آلهتهم التي يدعون من دون الله من شيء لما جاء أمر ربك وما زادوهم غير تتبيب»، وما ظلمنا تلك الأممَ بإهلاكهم، ولكن ظلموا أنفسهم بالكفرِ والمعاصي فاستحقّوا العذاب؛ فما دفعت عنهم آلهتُهم التي يعبدونها من دون الله شيئًا من العذابِ حين جاء أمرُ ربّك بهلاكهم، وما زادتهم عبادتُها غيرَ خسارةٍ وهلاك؛ ففي هذا أنّ المعبوداتِ الباطلةَ تخذل عابديها، وأنّ العبدَ يظلم نفسه بالمعصية؛ فلا تتّكل على ما يخذلك، ولا تظلم نفسك بمعصيةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العدل"],"heart_state":{"text":"أنّ العبدَ يظلم نفسه بالمعصية، وأنّ الباطلَ يخذل أهله."},"action":{"text":"لا تظلم نفسك بمعصيةِ الله، ولا تتّكل على ما لا ينفعك يوم الشدّة، فالمعبوداتُ الباطلةُ تخذل عابديها."}},{"n":102,"reflection":{"text":"«وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة إن أخذه أليم شديد»، ومثلُ ذلك الأخذِ الذي أخذ به تلك الأممَ يكون أخذُ ربّك للقرى الظالمةِ في كلِّ زمان، إنّ أخذه مؤلمٌ شديدٌ لا يُطاق؛ ففي هذا تخويفٌ لكلِّ ظالمٍ أن يأخذه الله بغتةً بأخذٍ أليم؛ فاحذر الظلمَ والإصرارَ عليه، فأخذُ الله للظالمين أليمٌ شديد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ العبدِ من أخذِ الله الأليمِ للظالمين."},"action":{"text":"احذر الظلمَ والإصرارَ على المعصية، فأخذُ الله للقرى الظالمةِ أليمٌ شديد، وراقب الله في كلِّ عملك."}}]},{"title":"يومُ القيامةِ المشهود، وانقسامُ الناس","range":[103,105],"theme":"أنّ في العذابِ آيةً لخائفِ الآخرة، وأنّ الناسَ يومئذٍ شقيٌّ وسعيد","verses":[{"n":103,"reflection":{"text":"«إن في ذلك لآية لمن خاف عذاب الآخرة ذلك يوم مجموع له الناس وذلك يوم مشهود»: إنّ في إهلاكِ الأممِ لعبرةً وعلامةً لمن يخاف عذابَ الآخرة (فأمّا الغافلُ فلا يعتبر)؛ ذلك اليومُ (القيامةُ) يومٌ يُجمع له الناسُ جميعًا للحساب، ويومٌ مشهودٌ يشهده الخلائقُ كلُّهم؛ ففي هذا أنّ خوفَ الآخرةِ يفتح بابَ الاعتبار؛ فاجعل خوفَ الآخرةِ في قلبك ليفتح لك بابَ العظةِ والعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ خوفَ الآخرةِ يورث الاعتبارَ والعمل."},"action":{"text":"أحيِ في قلبك خوفَ عذابِ الآخرة، فبه تعتبر بالآياتِ وتستعدّ ليومٍ يُجمع له الناسُ ويشهده الخلق."}},{"n":104,"reflection":{"text":"«وما نؤخره إلا لأجل معدود»، وما نؤخّر ذلك اليومَ (القيامة) إلا لوقتٍ محدودٍ معدودٍ في علمِ الله لا يتقدّم ولا يتأخّر؛ ففي هذا أنّ تأخّرَ القيامةِ ليس إهمالًا بل لأجلٍ مقدّر؛ فلا يغرّنّك تأخّرُ الحساب، فهو آتٍ في وقتِه المعدود؛ فاستعدّ له من الآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بتأخّرِ القيامة، فهي آتيةٌ لأجلٍ مقدّر."},"action":{"text":"لا يغرّنّك تأخّرُ يومِ القيامة، فهو آتٍ في أجلِه المعدود، فاستعدّ له بالعملِ الصالحِ من الآن."}},{"n":105,"reflection":{"text":"«يوم يأت لا تكلم نفس إلا بإذنه فمنهم شقي وسعيد»: يومَ يأتي ذلك اليومُ لا تتكلّم نفسٌ بشفاعةٍ ولا اعتذارٍ إلا بإذنِ الله، من هولِ الموقفِ وعظمةِ سلطانه؛ فالناسُ يومئذٍ فريقان: شقيٌّ استحقّ النار، وسعيدٌ استحقّ الجنّة؛ ففي هذا أنّ مآلَ الناسِ إلى فريقين لا ثالثَ لهما؛ فاعمل لتكون من السعداء، فليس بعد ذلك اليومِ إلا شقاءٌ أو سعادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من السعداء، إذ لا مآلَ إلا شقاءٌ أو سعادة."},"action":{"text":"اعمل جاهدًا لتكون من السعداء يوم القيامة، فالناسُ يومئذٍ شقيٌّ وسعيد، ولا كلامَ إلا بإذنِ الله."}}]},{"title":"مآلُ الأشقياءِ والسعداء","range":[106,108],"theme":"عذابُ أهلِ النارِ ونعيمُ أهلِ الجنّة، وأنّ عطاءَ الله لا ينقطع","verses":[{"n":106,"reflection":{"text":"«فأما الذين شقوا ففي النار لهم فيها زفير وشهيق»: فأمّا الذين شقوا بكفرهم ومعاصيهم ففي النارِ يُعذّبون، لهم فيها زفيرٌ (صوتٌ شديدٌ عند إخراجِ النفَس) وشهيقٌ (صوتٌ عند ردِّه) من شدّةِ العذابِ والكرب؛ ففي هذا تصويرُ شدّةِ عذابِ النار؛ فاحذر أسبابَ الشقاءِ التي تورد النار، والزم أسبابَ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من عذابِ النارِ واجتنابُ أسبابِ الشقاء."},"action":{"text":"احذر أسبابَ الشقاءِ من الكفرِ والمعاصي، واعمل بما ينجّيك من عذابِ النارِ وزفيرِها وشهيقها."}},{"n":107,"reflection":{"text":"«خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك إن ربك فعال لما يريد»: ماكثين في النارِ أبدًا ما دامت سماواتُ الآخرةِ وأرضُها (أي دوامًا لا انقطاعَ له)، إلا ما شاء ربّك من إخراجِ عصاةِ الموحّدين منها برحمته؛ إنّ ربّك فعّالٌ لما يريد لا معقّبَ لحكمه؛ ففي هذا خلودُ الكفارِ، ونفوذُ مشيئةِ الله؛ فسلّم لمشيئةِ الله وحكمته، واعلم أنه فعّالٌ لما يريد، فاطلب رحمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فعال لما يريد"],"heart_state":{"text":"التسليمُ لمشيئةِ الله النافذة، وطلبُ رحمته."},"action":{"text":"سلّم لمشيئةِ الله وحكمته، واعلم أنه فعّالٌ لما يريد، فاطلب رحمته والنجاةَ من عذابه بالإيمانِ والعمل."}},{"n":108,"reflection":{"text":"«وأما الذين سعدوا ففي الجنة خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك عطاء غير مجذوذ»، وأمّا الذين سعدوا بإيمانهم وعملهم ففي الجنّةِ ماكثين فيها أبدًا ما دامت سماواتُ الآخرةِ وأرضُها، إلا ما شاء ربّك من الزيادةِ في النعيمِ أو من تأخّرِ دخولِ بعضهم؛ عطاءً غيرَ مقطوعٍ ولا منقوصٍ بل دائمٌ متّصل؛ ففي هذا أنّ نعيمَ الجنّةِ دائمٌ لا ينقطع؛ فاعمل للنعيمِ الباقي الذي لا ينقطع، فعطاءُ الله لأهلِ الجنّةِ غيرُ مجذوذ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عطاء غير مجذوذ"],"heart_state":{"text":"الرجاءُ في نعيمِ الجنّةِ الدائمِ الذي لا ينقطع."},"action":{"text":"اعمل لنعيمِ الجنّةِ الدائم، فعطاءُ الله لأهلها غيرُ مقطوعٍ ولا منقوص، فاطلبه بالإيمانِ والعملِ الصالح."}}]},{"title":"لا شكَّ في بطلانِ عبادتهم، وتوفيةُ الأعمال","range":[109,111],"theme":"أنّ تقليدَ الآباءِ لا يصحّح الباطل، وأنّ الله يوفّي كلًّا عمله","verses":[{"n":109,"reflection":{"text":"«فلا تك في مرية مما يعبد هؤلاء ما يعبدون إلا كما يعبد آباؤهم من قبل وإنا لموفوهم نصيبهم غير منقوص»: فلا تكن يا محمد (والخطابُ لأمّته) في شكٍّ من بطلانِ ما يعبد هؤلاء المشركون، فما يعبدون إلا تقليدًا لآبائهم بلا حجّة، وإنا لمعطوهم نصيبهم من العذابِ كاملًا غيرَ منقوص؛ ففي هذا أنّ التقليدَ لا يصحّح الباطل، وأنّ جزاءَ الباطلِ واقعٌ كاملًا؛ فلا تشكّ في بطلانِ ما خالف الحقَّ ولو ورثه الناسُ عن آبائهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ ببطلانِ ما خالف الحقّ، ولو كان موروثًا متّبعًا."},"action":{"text":"لا تشكّ في بطلانِ كلِّ ما خالف التوحيدَ والحقّ ولو ورثه الناسُ عن آبائهم، فالتقليدُ لا يجعل الباطلَ حقًّا."},"qadiyya":{"title":"قضيّةُ قولٍ يُحتجّ له ولا يُحتجّ به","question":"قال الله لنبيّه: ﴿فلا تك في مرية مما يعبد هؤلاء﴾، ثمّ كشف عن الذي بأيديهم: ﴿ما يعبدون إلا كما يعبد آباؤهم من قبل﴾، ثمّ قرن بذلك: ﴿وإنا لموفوهم نصيبهم غير منقوص﴾.\nفحُكيت حجّتُهم على وجهها، وهي التوارثُ عن الآباء، ولم تُناقَش في مضمونها.\nفالقضيّة: بأيّ شيءٍ سقطت هذه الحجّةُ حتى لم تبلغ رتبة الشبهة؟ ثمّ: هل يرفعها اتّفاق الكثرة عليها؟ ثمّ: إذا لم يكن بأيديهم إلّا هذه، فلمَ قرن بها ذكرَ نصيبهم من الدنيا؟","background":"ولا يظهر موضعُ الإشكال حتى يُفرّق بين مقامين للقول:\nأن **يُحتجّ له**، فيُطلب له من خارجه دليلٌ يسنده.\nوأن **يُحتجّ به**، فيُجعل هو نفسُه سندًا لغيره.\nفالأوّل محتاج، والثاني مُغنٍ. ومن أنزل المحتاجَ منزلة المغني فقد جعل الدعوى دليلًا على نفسها.\nثمّ الرتبةُ بعد ذلك اثنتان، أعلاهما الدليلُ ودونه الشبهة، كما يقتضيه قولُه «فضلا عن»؛ فنفيُ الأدنى نفيٌ للأعلى من باب أولى.","what_happened":"بدأ السعديُّ بتعيين المخاطَب بالنهي فقال: «يقول الله تعالى، لرسوله محمد صلى الله عليه وسلم»، ثمّ عيّن المشار إليهم في ﴿هؤلاء﴾ فقال: «المشركون».\nثمّ فسّر النهي عن المرية: «أي: لا تشك في حالهم، وأن ما هم عليه باطل, فليس لهم عليه دليل شرعي ولا عقلي».\n⭐ ثمّ **حصر ما بأيديهم** فقال: «وإنما دليلهم وشبهتهم»، وساق الآية.\nثمّ حكم عليه بجملةٍ فيها القاعدةُ وعلّتُها: «ومن المعلوم أن هذا، ليس بشبهة، فضلا عن أن يكون دليلا، لأن أقوال ما عدا الأنبياء، يحتج لها لا يحتج بها».\nثمّ خصّ هؤلاء بالذكر: «خصوصا أمثال هؤلاء الضالين، الذين كثر خطأهم وفساد أقوالهم, في أصول الدين»، ثمّ فرّع عليه: «فإن أقوالهم، وإن اتفقوا عليها، فإنها خطأ وضلال».\n⭐ ثمّ فسّر ﴿وإنا لموفوهم نصيبهم غير منقوص﴾: «أي: لا بد أن ينالهم نصيبهم من الدنيا، مما كتب لهم»، ثمّ خاطب الناظر إليهم: «وإن كثر ذلك النصيب، أو راق في عينك, فإنه لا يدل على صلاح حالهم»، وعلّله: «فإن الله يعطي الدنيا من يحب، ومن لا يحب، ولا يعطي الإيمان والدين الصحيح، إلا من يحب».\nثمّ ختم: «والحاصل أنه لا يغتر باتفاق الضالين، على قول الضالين من آبائهم الأقدمين، ولا على ما خولهم الله، وآتاهم من الدنيا».","the_verdict":"فالحاصلُ أنّ حجّتهم سقطت بردّها إلى مصدرها، لا بمناقشة مضمونها.\nفالذي بأيديهم قولُ آباء، والقولُ إنّما يصير سندًا بأن يكون قائلُه نبيًّا، كما علّل الإمامُ بقوله «لأن أقوال ما عدا الأنبياء، يحتج لها لا يحتج بها»؛ فإذا لم يكن قائلُه نبيًّا رجع دعوى تطلب بيّنة.\n⭐ ومن هنا نُفي عنه وصفُ الشبهة قبل وصف الدليل، فلم يُنزَّل رتبةً، بل أُخرج من الباب كلّه.\nوأمّا الكثرة فقد جاء قيدُها في نصّه: «وإن اتفقوا عليها». **فالاتّفاق زيادةٌ في عدد القائلين، لا في جنس القول.**\n⭐ وموضعُ الدقّة الذي يفوت الناقلَ العجل: أنّ في كلامه جملتين لا جملةً واحدة.\nفالأولى عامّة، وهي نفيُ الحجّيّة عن أقوال من عدا الأنبياء. والثانيةُ خاصّةٌ بهؤلاء، وهي الحكمُ بالخطأ والضلال؛ ودليلُ خصوصها مرجعُ الضمير في «فإن أقوالهم»، فهو عائدٌ على «أمثال هؤلاء الضالين» قبله.\nفمن نقل الثانية إلى غير من قُصرت عليه فجعل كلَّ قولٍ لغير نبيٍّ ضلالًا فقد وسّع ما ضيّقه الإمام. **ونفيُ الحجّيّة غيرُ نفي الصحّة**؛ فالقولُ قد يكون صوابًا بدليله لا بقائله.\n⭐ وأمّا سعةُ الدنيا فليست ممّا احتجّوا به، فقد حصر ما بأيديهم بقوله «وإنما دليلهم وشبهتهم»؛ وإنّما هي ما يقع في عين الناظر، ولذلك قال: «أو راق في عينك»، فخاطب الرائي لا المرئيّ.\nفأسقطها لا لأنّها حجّتُهم، بل لئلّا تصير حجّةً عليك لهم؛ إذ العطاء يقع لمن يحبّه الله ولمن لا يحبّه، والدينُ الصحيحُ مخصوصٌ بمن يحبّه، فما عمّ لم يصلح علامةً على التخصيص.\nولذلك جمع في خاتمته بين البابين: اتّفاقُهم على قول الآباء، وما خُوّلوه من الدنيا؛ وكلاهما موضعُ اغترار الناظر.","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: افصل القول عن قائله في مسألةٍ تعمل بها اليوم.** خذ أمرًا تفعله في دينك أو مالك وسله: ما الذي يسنده؟ فإن لم تجد إلّا أنّ أهلك عليه أو أنّ الناس عليه فقد بان أنّك بلا سند.\nوالثاني: أسقط العدد المجرّد من الميزان. إذا جرى في نفسك أنّ الناس كلَّهم يفعلونه فاستبدل به سؤالًا واحدًا: ومن الذي أوجبه؟ فإن كان الجوابُ عددًا مجرّدًا فليس بجواب؛ ولو صنع العددُ وحدَه حجّةً لانقلب خطأُ هؤلاء صوابًا بكثرة من يقول به.\nوالثالث: لا تقس الحال بالنصيب. انظر فيمن تقتدي به: أاقتديتَ به لدينه أم لسعة دنياه؟ فإن كان الثاني فبدّل المقياس، فإنّ الدنيا تُعطى لمن يحبّه الله ولمن لا يحبّه، كما قرّر الإمام.","grade":"ma'thur","source":"تفسيرُ السعديّ لمطلع الآية («يقول الله تعالى، لرسوله محمد صلى الله عليه وسلم»)، وتعيينُه المشار إليهم («المشركون»)، والنهيُ عن المرية («أي: لا تشك في حالهم»)، وحصرُه ما بأيديهم («وإنما دليلهم وشبهتهم»)، والقاعدةُ وعلّتُها («ومن المعلوم أن هذا، ليس بشبهة»)، وتخصيصُه بالذكر («خصوصا أمثال هؤلاء الضالين»)، وتفريعُه («فإن أقوالهم، وإن اتفقوا عليها»)، وتفسيرُ النصيب («أي: لا بد أن ينالهم»)، وخطابُه للناظر («أو راق في عينك»)، وتعليلُه («فإن الله يعطي الدنيا من يحب»)، وخاتمتُه («والحاصل أنه لا يغتر باتفاق الضالين»): كلُّها بنصّها في تفسير السعديّ (١١:١٠٩).","honesty":"وممّا يجب أن يُقال:\nأمّا التفريقُ بين ما يُحتجّ له وما يُحتجّ به فلفظُه بنصّه؛ وإنّما الذي لنا شرحُه بأنّ الأوّل محتاج والثاني مُغنٍ، وقولُنا إنّ من سوّى بينهما فقد جعل الدعوى دليلًا على نفسها. وترتيبُنا الدليلَ فوق الشبهة عبارةٌ منّا أخذناها من قوله «فضلا عن»، ولم يحدّهما هو بحدّ.\nوأمّا قولُنا إنّ الحجّة سقطت بردّها إلى مصدرها لا بمناقشة مضمونها، وإنّ الاتّفاق زيادةٌ في العدد لا في الجنس، وإنّ ما عمّ لا يصلح علامةً على التخصيص، وإنّ نفي الحجّيّة غير نفي الصحّة، فاستنباطٌ منّا على كلامه المجموع.\nوأمّا تمييزُنا بين جملته العامّة وجملته الخاصّة، واستدلالُنا على خصوص الثانية بمرجع الضمير، فترتيبٌ منّا على نصّه لحفظ قيده.\nوأمّا قولُنا إنّ سعة الدنيا ليست ممّا احتجّوا به بل ممّا يقع في عين الناظر، فقراءةٌ منّا جمعنا فيها بين حصره وبين خطابه في «أو راق في عينك».\nوالثلاثةُ التي في آخر القضيّة اختباراتٌ رتّبناها نحن.\nولم نتعرّض لحجّيّة الإجماع الشرعيّ؛ فإنّ الكلام في اتّفاقٍ قيّده الإمامُ بأنّه اتّفاقُ من وصفهم بالضلال.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":110,"reflection":{"text":"«ولقد آتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وإنهم لفي شك منه مريب»، ولقد آتينا موسى التوراةَ فاختلف قومُه فيها فآمن بعضٌ وكفر بعض، ولولا كلمةٌ سبقت من ربّك بتأخيرِ الحسابِ إلى يوم القيامةِ لعُجّل القضاءُ بينهم في الدنيا؛ وإنّ قومك (أو اليهود) لفي شكٍّ من القرآنِ (أو التوراةِ) موقعٍ في الريبة؛ ففي هذا تسليةٌ للنبيِّ بأنّ الاختلافَ على الأنبياءِ سنّةٌ ماضية؛ فلا يحزنك اختلافُ الناسِ على الحقّ، فقد اختُلف على موسى من قبلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على اختلافِ الناسِ على الحقّ، فتلك سنّةٌ ماضية."},"action":{"text":"لا يحزنك اختلافُ الناسِ وشكُّهم في الحقّ، فقد اختُلف على الأنبياءِ قبلك، والزم الحقَّ وابلّغه واصبر."}},{"n":111,"reflection":{"text":"«وإن كلا لما ليوفينهم ربك أعمالهم إنه بما يعملون خبير»، وإنّ كلَّ فريقٍ من المختلفين والمكذّبين والمؤمنين ليوفّينّهم ربّك جزاءَ أعمالهم كاملةً يوم القيامة، إنه بما يعملون خبيرٌ لا يخفى عليه من أعمالهم شيء؛ ففي هذا أنّ كلَّ عاملٍ مجزيٌّ بعمله عدلًا، وأنّ الله خبيرٌ بكلِّ عمل؛ فأحسن عملك، واعلم أنّ الله سيوفّيك جزاءه، وأنه خبيرٌ بما تعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الخبير"],"heart_state":{"text":"استحضارُ توفيةِ الله لكلِّ عملٍ، وأنه خبيرٌ به."},"action":{"text":"أحسن عملك واعلم أنّ الله سيوفّيك جزاءه كاملًا، فهو خبيرٌ بكلِّ ما تعمل، لا يضيع عنده عملٌ ولا يخفى."}}]},{"title":"الأمرُ الجامع: فاستقم كما أُمرت، ولا تركن إلى الظالمين","range":[112,113],"theme":"أعظمُ وصيّةٍ في السورة: الاستقامةُ بلا طغيان، والبعدُ عن الظالمين","verses":[{"n":112,"reflection":{"text":"«فاستقم كما أمرت ومن تاب معك ولا تطغوا إنه بما تعملون بصير»: فاستقم يا محمد على دينِ الله وأمره كما أمرك ربّك من غيرِ غلوٍّ ولا تقصير، ومعك من تاب من المؤمنين، ولا تطغوا بتجاوزِ حدودِ الله، إنه بما تعملون بصيرٌ يراكم ويجازيكم؛ فهذه الآيةُ التي قال عنها النبيُّ ﷺ إنها شيّبته لعظمِ ما فيها من التكليفِ بالاستقامة؛ ففي هذا أنّ لبَّ الدينِ الاستقامةُ على أمرِ الله بلا إفراطٍ ولا تفريط؛ فاستقم على أمرِ الله كما أُمرت، واحذر الطغيانَ والغلوّ، فالله بصيرٌ بعملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البصير"],"heart_state":{"text":"الاستقامةُ على أمرِ الله بلا غلوٍّ ولا طغيان."},"action":{"text":"استقم على أمرِ الله في عقيدتك وعبادتك وأخلاقك كما أُمرت، بلا إفراطٍ ولا تفريط، واحذر الطغيانَ ومجاوزةَ الحدّ."}},{"n":113,"reflection":{"text":"«ولا تركنوا إلى الذين ظلموا فتمسكم النار وما لكم من دون الله من أولياء ثم لا تنصرون»، ولا تميلوا إلى الذين ظلموا (الكفارِ والعصاة) ركونًا برضًا بظلمهم أو مداهنةٍ أو معاونةٍ، فتصيبكم النارُ بسببِ ركونكم إليهم، وليس لكم من دون الله أنصارٌ يمنعونكم من عذابه، ثم لا تُنصرون؛ ففي هذا النهيُ عن مجرّدِ الميلِ إلى الظالمين فضلًا عن معاونتهم؛ فلا تركن إلى ظالمٍ ولا ترضَ بظلمه ولا تُعِنه، فالركونُ إلى الظالمين سببٌ لمسِّ النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الركونِ إلى الظالمين أو الرضا بظلمهم."},"action":{"text":"لا تمِل إلى الظالمين ولا ترضَ بظلمهم ولا تُعِنهم عليه، فمجرّدُ الركونِ إليهم سببٌ لمسِّ النار، فباعد نفسك عنهم."}}]},{"title":"إقامةُ الصلاة، وأنّ الحسناتِ تمحو السيئات، والصبر","range":[114,115],"theme":"أنّ الصلاةَ تمحو الذنوب، وأنّ الله لا يضيع أجرَ المحسنين","verses":[{"n":114,"reflection":{"text":"«وأقم الصلاة طرفي النهار وزلفا من الليل إن الحسنات يذهبن السيئات ذلك ذكرى للذاكرين»، وأقم الصلاةَ في طرفي النهار (الصبحِ والظهرِ والعصر) وساعاتٍ من الليل (المغربِ والعشاء)، إنّ الحسناتِ (ومنها الصلواتُ الخمس) يُذهبن الذنوبَ الصغائرَ ويمحونها؛ ذلك عظةٌ وتذكرةٌ للذين يتّعظون؛ وقد نزلت في رجلٍ أصاب من امرأةٍ قبلةً فجاء تائبًا (البخاري ومسلم)؛ ففي هذا أنّ الطاعاتِ تكفّر السيئات؛ فأتبع السيئةَ الحسنةَ تمحها، وحافظ على الصلواتِ الخمسِ فهي ممحاةٌ للذنوب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المحافظةُ على الصلاة، وإتباعُ السيئةِ الحسنةَ لتمحوها."},"action":{"text":"حافظ على الصلواتِ الخمسِ في أوقاتها، وإذا أذنبت فأتبع الذنبَ حسنةً وتوبةً، فإنّ الحسناتِ يُذهبن السيئات."},"sabab":{"text":"جاء رجلٌ إلى النبيِّ ﷺ فأخبره أنه أصاب من امرأةٍ قُبلةً (دون الفاحشة) وطلب أن يُقام عليه الحدّ، فحضرت الصلاةُ فصلّى مع النبيِّ ﷺ، فلما فرغ سأله فتلا عليه هذه الآية، فقال: «هي له خاصّةً أم للناس كافّةً؟» قال: «بل للناسِ كافّة» (متّفقٌ عليه، عن ابن مسعود).","source":"صحيح البخاري ومسلم","grade":"ma'thur"}},{"n":115,"reflection":{"text":"«واصبر فإن الله لا يضيع أجر المحسنين»، واصبر يا محمد (وأمّتُه) على طاعةِ الله وعلى أذى الناسِ وعلى المصائب، فإنّ الله لا يضيع أجرَ من أحسن عمله بل يجزيه أوفى الجزاء؛ ففي هذا أنّ الصبرَ إحسانٌ لا يضيع أجرُه؛ فاصبر على طاعةِ الله وابتلائه، واعلم أنّ أجرك محفوظٌ عند الله لا يضيع.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا يضيع أجر المحسنين"],"heart_state":{"text":"الصبرُ على الطاعةِ والبلاءِ، واليقينُ بحفظِ الله للأجر."},"action":{"text":"اصبر على طاعةِ الله وعلى ما يصيبك، واعلم أنّ الله لا يضيع أجرَ المحسنين، فأجرُ صبرك محفوظٌ عنده."}}]},{"title":"غيابُ الناهين عن الفساد، وعدلُ الله في الإهلاك","range":[116,117],"theme":"أنّ قلّةَ الآمرين بالمعروفِ سببُ الهلاك، وأنّ الله لا يهلك المصلحين ظلمًا","verses":[{"n":116,"reflection":{"text":"«فلولا كان من القرون من قبلكم أولو بقية ينهون عن الفساد في الأرض إلا قليلا ممن أنجينا منهم واتبع الذين ظلموا ما أترفوا فيه وكانوا مجرمين»: فهلّا كان في الأممِ قبلكم أصحابُ دينٍ وفضلٍ (بقيّةٍ من خير) ينهون عن الفسادِ في الأرض فينجون بذلك؟ لم يكن إلا قليلٌ منهم أنجيناهم لقيامهم بالنهي، وأمّا الظالمون فاتّبعوا ما عُوّدوا من الترفِ والشهواتِ وأعرضوا عن النهي، وكانوا مجرمين؛ ففي هذا أنّ تركَ النهيِ عن المنكرِ سببُ الهلاك، وأنّ النجاةَ لأهلِ الإصلاح؛ فكن من الناهين عن الفساد، فبهم تُدفع العقوبةُ عن الأمّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"القيامُ بالنهيِ عن المنكرِ والفساد، فبه تُدفع العقوبة."},"action":{"text":"كن من الآمرين بالمعروفِ الناهين عن المنكرِ والفساد، فبهم ينجّي الله الأمم، وتركُ ذلك سببٌ للهلاك."}},{"n":117,"reflection":{"text":"«وما كان ربك ليهلك القرى بظلم وأهلها مصلحون»، وما كان من عدلِ ربّك وحكمته أن يهلك القرى ظلمًا منه لها وأهلُها مصلحون في أعمالهم عادلون فيما بينهم؛ وإنما يهلكهم بظلمهم أنفسهم وفسادهم؛ ففي هذا أنّ الصلاحَ يدفع الهلاك، وأنّ الله عدلٌ لا يظلم؛ فاجتهد في إصلاحِ نفسك ومجتمعك، فبالإصلاحِ تُدفع العقوبةُ ويعمّ الأمنُ والبركة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الإصلاحَ يدفع العقوبة، وأنّ الله لا يهلك المصلحين ظلمًا."},"action":{"text":"اجتهد في الإصلاحِ في نفسك وأهلك ومجتمعك، فالله لا يهلك أهلَ الإصلاح، وبالصلاحِ تُدفع العقوباتُ وتعمّ البركة."}}]},{"title":"حكمةُ الاختلاف، وأهلُ الرحمة","range":[118,119],"theme":"أنّ الاختلافَ سنّةٌ إلا من رحم الله، وأنّ لذلك خلقهم","verses":[{"n":118,"reflection":{"text":"«ولو شاء ربك لجعل الناس أمة واحدة ولا يزالون مختلفين»، ولو شاء ربّك لجعل الناسَ كلَّهم أمةً واحدةً على الهدى (بأن يجبرهم عليه)، ولكن اقتضت حكمتُه أن يتركهم مختارين، فلا يزالون مختلفين في الأديانِ والأهواءِ ابتلاءً؛ ففي هذا أنّ الاختلافَ واقعٌ بمشيئةِ الله وحكمته؛ فلا يحملنّك اختلافُ الناسِ على ترك الحقّ، والزم الجماعةَ على الهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ رغمَ اختلافِ الناس، وقبولُ حكمةِ الابتلاء."},"action":{"text":"الزم الحقَّ والهدى ولا يزعزعك اختلافُ الناس، فاختلافُهم واقعٌ بحكمةِ الله في ابتلائهم، فكن مع أهلِ الحقّ."}},{"n":119,"reflection":{"text":"«إلا من رحم ربك ولذلك خلقهم وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين»: إلا من رحمهم ربّك بالهدايةِ والتوفيق فاتّفقوا على الحقِّ ولم يختلفوا فيه، ولأجلِ الرحمةِ (أو للاختلافِ ابتلاءً) خلقهم؛ وتمّت كلمةُ ربّك وحقّ قضاؤه العدلُ: لأملأنّ جهنمَ من عصاةِ الجنِّ والناسِ أجمعين ممّن اختار الكفر؛ ففي هذا أنّ الناجين من الاختلافِ هم أهلُ رحمةِ الله؛ فاطلب رحمةَ الله التي تجمعك على الحقّ، وتعوّذ من أسبابِ دخولِ النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمة"],"heart_state":{"text":"طلبُ رحمةِ الله التي تجمع على الحقّ، والتعوّذُ من النار."},"action":{"text":"اسأل الله رحمته التي تهديك وتجمعك على الحقّ، واحذر أسبابَ دخولِ النارِ التي توعّد الله بملئها من العصاة."}}]},{"title":"تثبيتُ الفؤادِ بالقصص، وختمُ السورةِ بالعبادةِ والتوكّل","range":[120,123],"theme":"أنّ قصصَ الأنبياءِ تثبّت القلب، وأنّ الأمرَ كلَّه لله فاعبده وتوكّل عليه","verses":[{"n":120,"reflection":{"text":"«وكلا نقص عليك من أنباء الرسل ما نثبت به فؤادك وجاءك في هذه الحق وموعظة وذكرى للمؤمنين»، وكلَّ خبرٍ نقصّه عليك يا محمد من أخبارِ الرسلِ (وصبرِهم ونصرِهم) إنما نقصّه لنثبّت به قلبك على الحقِّ والصبر؛ وجاءك في هذه السورة (أو القصص) الحقُّ الذي لا شكَّ فيه، وموعظةٌ تزجر، وذكرى وتذكيرٌ للمؤمنين خاصّة؛ ففي هذا أنّ قصصَ الأنبياءِ غذاءٌ للقلبِ وتثبيتٌ له؛ فتدبّر قصصَ الأنبياءِ لتثبّت قلبك وتصبر كصبرهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ قصصِ الأنبياءِ لتثبيتِ القلبِ على الحقِّ والصبر."},"action":{"text":"اقرأ قصصَ الأنبياءِ وتدبّرها لتثبيت قلبك على الحقّ، وتعلّم منها الصبرَ واليقينَ كما ثبّتت قلبَ نبيّك ﷺ."}},{"n":121,"reflection":{"text":"«وقل للذين لا يؤمنون اعملوا على مكانتكم إنا عاملون»، وقل يا محمد للذين لا يؤمنون: اعملوا على طريقتكم وحالِكم التي أنتم عليها فإنا عاملون على طريقتنا، وسترون عاقبةَ الفريقين؛ ففي هذا تهديدٌ وثقةٌ بأنّ العاقبةَ لأهلِ الحقّ؛ فاثبت على عملك للحقّ، ولا يزعزعك إعراضُ المعرضين، فالعاقبةُ للمتقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على العملِ للحقِّ رغمَ إعراضِ المعرضين."},"action":{"text":"اثبت على طريقِ الحقِّ واعمل له، ولا يزعزعك إعراضُ من لا يؤمن، فاعمل على مكانتك واثقًا بأنّ العاقبةَ لأهلِ الحقّ."}},{"n":122,"reflection":{"text":"«وانتظروا إنا منتظرون»، وانتظروا ما يؤول إليه أمرُنا وأمرُكم من العاقبة، إنا منتظرون معكم لنرى لمن تكون العاقبةُ الحميدة؛ ففي هذا وعيدٌ للمكذّبين وثقةٌ بنصرِ الله لأوليائه؛ فاصبر وانتظر وعدَ الله، فهو آتٍ لا محالة، والعاقبةُ لأهلِ التقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"انتظارُ وعدِ الله بالصبرِ والثقةِ بنصره."},"action":{"text":"اصبر وانتظر وعدَ الله بنصرِ الحقِّ وأهله، واثق بأنّ العاقبةَ للمتقين، فوعدُ الله آتٍ لا محالة."}},{"n":123,"reflection":{"text":"«ولله غيب السماوات والأرض وإليه يرجع الأمر كله فاعبده وتوكل عليه وما ربك بغافل عما تعملون»، ولله وحده علمُ غيبِ السماواتِ والأرضِ لا يعلمه سواه، وإليه يرجع الأمرُ كلُّه يوم القيامةِ فيحكم فيه بعدله، فاعبده وحده مخلصًا وتوكّل عليه في أمورك كلِّها، وما ربّك بغافلٍ عمّا تعملون بل هو مطّلعٌ محصٍ فمجازٍ عليه؛ فخُتمت السورةُ بجماعِ الدين: إفرادِ الله بالعبادةِ والتوكّل؛ فاعبد الله وحده وتوكّل عليه، واعلم أنه ليس بغافلٍ عن عملك فأحسنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عالم الغيب","الوكيل"],"heart_state":{"text":"إفرادُ الله بالعبادةِ والتوكّل، واستحضارُ اطّلاعِه على العمل."},"action":{"text":"اعبد الله وحده وتوكّل عليه في كلِّ أمرك، وأحسن عملك مستحضرًا أنّ الله ليس بغافلٍ عمّا تعمل، وإليه يرجع الأمرُ كلُّه."}}]}],"coverage":{"covered":123,"total":123}};
